 * Commands:
 *   clone        - Clone a repository
 *   learn        - Analyze repository (default)
 *   generate     - Generate code from prompt (aliases: gen, code, feature)
 *   generate-spec - Generate from spec file
 *   plan         - Create implementation plan
 *   commit       - Stage and commit with smart message
 *   push         - Push and open PR
 *   status       - Smart git status with gitgen context
 *   state        - Git-backed state store (refs/.gitgen/state)
 *   remember     - Save files to gitgen branch (aliases: remembered)
 *   forget       - Remove files from gitgen branch
 *   restore      - Restore files from gitgen branch
 *   configure    - Generate plugins for AI coding assistants
 */
import { createCloneCommand } from './clone.js';
import { createLearnCommand } from './learn.js';
import { createGenerateCommand, createGenerateFromSpecCommand } from './generate.js';
import { createPlanCommand } from './plan.js';
import { createInitCommand } from './init.js';
import { createTestCommand } from './test.js';
import { createDiffCommand } from './diff.js';
import { createAskCommand } from './ask.js';
import { createRememberCommand } from './remember.js';
import { createForgetCommand } from './forget.js';
import { createStatusCommand } from './status.js';
import { createCommitCommand } from './commit.js';
