import { createChangelogCommand } from './changelog.js';
// === Command Registry ===
const registry = new Map();
/**
 * Register a command
 */
export function registerCommand(command) {
    registry.set(command.name, command);
    // Also register aliases
    if (command.aliases) {
        for (const alias of command.aliases) {
            registry.set(alias, command);
        }
    }
}
/**
 * Get a command by name or alias
 */
export function getCommand(name) {
    return registry.get(name);
}
/**
 * Get all registered commands (unique, no aliases)
 */
export function getAllCommands() {
    const seen = new Set();
    const commands = [];
    for (const command of registry.values()) {
        if (!seen.has(command.name)) {
            seen.add(command.name);
            commands.push(command);
        }
    }
    return commands;
}
/**
 * Check if a command is registered
 */
export function isCommandRegistered(name) {
    return registry.has(name);
}
/**
 * Get command names (for help/completion)
 */
export function getCommandNames() {
    return getAllCommands().map(c => c.name);
}
// === Register Built-in Commands ===
