export { detectCommitFormat, validateCommitMessage, formatCommitMessage, inferCommitType, } from './detector.js';
export { CONVENTIONAL_TYPES, parseConventionalCommit, formatConventionalCommit, validateConventionalCommit, suggestCommitMessage, } from './conventional.js';

/**
 * Controller module - registry, factory, and exports
 */
import { createCLIController } from './cli/index.js';
import { createClaudeCodeController } from './claude-code/index.js';
// === Controller Registry ===
const registry = new Map();
/**
 * Register a controller type
 */
export function registerController(type, factory, description) {
    registry.set(type, { type, factory, description });
}
/**
 * Get a controller registration
 */
export function getControllerRegistration(type) {
    return registry.get(type);
}
/**
 * Get all registered controller types
 */
export function getRegisteredControllers() {
    return Array.from(registry.keys());
}
/**
 * Check if a controller type is registered
 */
export function isControllerRegistered(type) {
    return registry.has(type);
}
// === Controller Factory ===
/**
 * Create a controller instance by type
 */
export async function createController(type, context) {
    const registration = registry.get(type);
    if (!registration) {
        throw new Error(`Unknown controller type: ${type}`);
    }
    const controller = await registration.factory(context);
    await controller.initialize(context);
    return controller;
}
/**
 * Create the default controller (CLI)
 */
export async function createDefaultController(context) {
    return createController('cli', context);
}
// === Register Built-in Controllers ===
// CLI Controller
registerController('cli', async () => createCLIController(), 'Terminal-based controller for command-line operation');
// Claude Code Controller
registerController('claude-code', async () => createClaudeCodeController(), 'Agentic controller with conversation state, tools, and autonomous operation');
export { BaseController } from './base.js';
export { CLIController, createCLIController } from './cli/index.js';
export { ClaudeCodeController, createClaudeCodeController } from './claude-code/index.js';
export { ConversationState, LoopStateManager } from './claude-code/state.js';
export { createReadFileTool, createWriteFileTool, createEditFileTool, createExecuteCommandTool, createSearchFilesTool, createGitStatusTool, createUpdatePlanTool, createUpdateChangelogTool, createDefaultTools, } from './claude-code/tools.js';

/**
 * Core module - shared types, interfaces, and execution context
 */
// Re-export all types
export * from './types.js';
// Re-export context utilities
export { createContext, getEffectiveWorkingDir, isDryRun, isVerbose, isWorktree, createWorktreeContext, getModelFromEnv, getControllerFromEnv, validateContext, setDefaultContext, getDefaultContext, clearDefaultContext, } from './context.js';
// Re-export prompt type registry
export { registerPromptType, getPromptType, isPromptType, getAllPromptTypes, getPromptTypeNames, DEFAULT_PROMPT_TYPE, } from './prompt-types.js';

/**
 * Gen Branch - Opt-in file storage on orphan branch
 *
 * Stores selected files on a `.gitgen` branch without touching the working tree.
 * Uses git plumbing commands for safe, isolated operations.
 */
import { execSync, spawnSync } from 'node:child_process';
import { existsSync, mkdtempSync, rmSync, readFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
const GEN_BRANCH = 'gitgen';
const MAX_RETRIES = 3;
export class GenBranchError extends Error {
    code;
    constructor(message, code) {
        super(message);
        this.code = code;
        this.name = 'GenBranchError';
    }
}
/**
 * Resolve the current gen branch commit, or null if not initialized
 */
function resolveGenCommit(cwd) {
    try {
        const result = execSync(`git rev-parse --verify -q refs/heads/${GEN_BRANCH}`, {
            cwd,
            encoding: 'utf-8',
            stdio: ['pipe', 'pipe', 'pipe'],
        }).trim();
        return result || null;
    }
    catch {
        return null;
    }
}
/**
 * Create a blob from content and return its OID
 */
function createBlob(content, cwd) {
    const result = spawnSync('git', ['hash-object', '-w', '--stdin'], {
        cwd,
        input: content,
        encoding: 'utf-8',
        stdio: ['pipe', 'pipe', 'pipe'],
    });
    if (result.status !== 0) {
        throw new GenBranchError(`Failed to create blob: ${result.stderr}`, 'GIT_ERROR');
    }
    return result.stdout.trim();
}
/**
 * Execute a write operation with CAS retry logic
 */
function executeWrite(cwd, operation) {
    let retries = 0;
    while (retries < MAX_RETRIES) {
        const currentCommit = resolveGenCommit(cwd);
        const tempDir = mkdtempSync(join(tmpdir(), 'gitgen-gen-'));
        const tempIndex = join(tempDir, 'index');
        try {
            const env = { ...process.env, GIT_INDEX_FILE: tempIndex };
            // Set up temp index with current tree if exists
            if (currentCommit) {
                execSync(`git read-tree ${currentCommit}`, {
                    cwd,
                    env,
                    stdio: ['pipe', 'pipe', 'pipe'],
                });
            }
            // Execute the operation
            const { tree, message } = operation(tempIndex, currentCommit);
            // Create commit
            const parentArgs = currentCommit ? ['-p', currentCommit] : [];
            const commitResult = spawnSync('git', ['commit-tree', tree, ...parentArgs, '-m', message], {
                cwd,
                encoding: 'utf-8',
                stdio: ['pipe', 'pipe', 'pipe'],
            });
            if (commitResult.status !== 0) {
                throw new GenBranchError(`Failed to create commit: ${commitResult.stderr}`, 'GIT_ERROR');
            }
            const newCommit = commitResult.stdout.trim();
            // Update ref with CAS
            const updateArgs = currentCommit
                ? ['update-ref', `refs/heads/${GEN_BRANCH}`, newCommit, currentCommit]
                : ['update-ref', `refs/heads/${GEN_BRANCH}`, newCommit];
            const updateResult = spawnSync('git', updateArgs, {
                cwd,
                encoding: 'utf-8',
                stdio: ['pipe', 'pipe', 'pipe'],
            });
            if (updateResult.status !== 0) {
                // CAS failed, retry
                retries++;
                continue;
            }
            return newCommit;
        }
        finally {
            // Clean up temp index
            try {
                rmSync(tempDir, { recursive: true, force: true });
            }
            catch {
                // Ignore cleanup errors
            }
        }
    }
    throw new GenBranchError('Concurrent update detected. Please retry the operation.', 'CONCURRENT_UPDATE');
}
/**
 * Save a file to the gen branch
 */
export function save(filePath, content, options = {}) {
    const cwd = options.cwd || process.cwd();
    return executeWrite(cwd, (tempIndex) => {
        const env = { ...process.env, GIT_INDEX_FILE: tempIndex };
        // Create blob for content
        const contentBlob = createBlob(content, cwd);
        // Update index with content
        execSync(`git update-index --add --cacheinfo 100644 ${contentBlob} ${filePath}`, {
            cwd,
            env,
            stdio: ['pipe', 'pipe', 'pipe'],
        });
        // Write tree
        const tree = execSync('git write-tree', {
            cwd,
            env,
            encoding: 'utf-8',
            stdio: ['pipe', 'pipe', 'pipe'],
        }).trim();
        return { tree, message: `gen: update ${filePath}` };
    });
}
/**
 * Save a file from the working directory to the gen branch
 */
export function saveFile(filePath, options = {}) {
    const cwd = options.cwd || process.cwd();
    const fullPath = join(cwd, filePath);
    if (!existsSync(fullPath)) {
        throw new GenBranchError(`File not found: ${filePath}`, 'FILE_NOT_FOUND');
    }
    const content = readFileSync(fullPath);
    return save(filePath, content, options);
}
/**
 * Restore a file from the gen branch
 */
export function restore(filePath, options = {}) {
    const cwd = options.cwd || process.cwd();
    const currentCommit = resolveGenCommit(cwd);
    if (!currentCommit) {
        throw new GenBranchError('Gen branch not initialized', 'NOT_INITIALIZED');
    }
    try {
        // Use commit hash directly to avoid ambiguity with .gitgen being interpreted as path
        const result = spawnSync('git', ['cat-file', '-p', `${currentCommit}:${filePath}`], {
            cwd,
            stdio: ['pipe', 'pipe', 'pipe'],
        });
        if (result.status !== 0) {
            throw new GenBranchError(`File not found on gen branch: ${filePath}`, 'FILE_NOT_FOUND');
        }
        return result.stdout;
    }
    catch (error) {
        if (error instanceof GenBranchError) {
            throw error;
        }
        throw new GenBranchError(`File not found on gen branch: ${filePath}`, 'FILE_NOT_FOUND');
    }
}
/**
 * List files on the gen branch
 */
export function list(options = {}) {
    const cwd = options.cwd || process.cwd();
    const currentCommit = resolveGenCommit(cwd);
    if (!currentCommit) {
        return [];
    }
    try {
        // Use commit hash directly to avoid ambiguity with .gitgen being interpreted as path
        const result = execSync(`git ls-tree -r --name-only ${currentCommit}`, {
            cwd,
            encoding: 'utf-8',
            stdio: ['pipe', 'pipe', 'pipe'],
        });
        return result.trim().split('\n').filter(Boolean);
    }
    catch {
        return [];
    }
}
/**
 * Delete a file from the gen branch
 */
export function del(filePath, options = {}) {
    const cwd = options.cwd || process.cwd();
    const currentCommit = resolveGenCommit(cwd);
    if (!currentCommit) {
        throw new GenBranchError('Gen branch not initialized', 'NOT_INITIALIZED');
    }
    // Check if file exists (use commit hash to avoid path ambiguity)
    try {
        execSync(`git cat-file -e ${currentCommit}:${filePath}`, {
            cwd,
            stdio: ['pipe', 'pipe', 'pipe'],
        });
    }
    catch {
        throw new GenBranchError(`File not found on gen branch: ${filePath}`, 'FILE_NOT_FOUND');
    }
    return executeWrite(cwd, (tempIndex) => {
        const env = { ...process.env, GIT_INDEX_FILE: tempIndex };
        // Remove from index (force-remove works regardless of working tree state)
        execSync(`git update-index --force-remove ${filePath}`, {
            cwd,
            env,
            stdio: ['pipe', 'pipe', 'pipe'],
        });
        // Write tree
        const tree = execSync('git write-tree', {
            cwd,
            env,
            encoding: 'utf-8',
            stdio: ['pipe', 'pipe', 'pipe'],
        }).trim();
        return { tree, message: `gen: delete ${filePath}` };
    });
}
/**
 * Get the current head commit of the gen branch
 */
export function head(options = {}) {
    const cwd = options.cwd || process.cwd();
    return resolveGenCommit(cwd);
}
/**
 * Check if the gen branch exists
 */
export function exists(options = {}) {
    const cwd = options.cwd || process.cwd();
    return resolveGenCommit(cwd) !== null;
}
// Export as namespace
export const genBranch = {
    save,
    saveFile,
    restore,
    list,
    del,
    head,
    exists,
    GEN_BRANCH,
    GenBranchError,
};
export default genBranch;

/**
 * gh-models integration
 *
 * Soft dependency on GitHub's gh-models CLI extension.
 * Provides prompt export, evaluation, and test generation.
 */
import { execSync } from 'node:child_process';
import { existsSync, readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { dirname } from 'node:path';
/**
 * Check if gh CLI is installed
 */
export function hasGhCli() {
    try {
        execSync('gh --version', { stdio: 'pipe' });
        return true;
    }
    catch {
        return false;
    }
}
/**
 * Check if gh-models extension is installed
 */
export function hasGhModels() {
    if (!hasGhCli())
        return false;
    try {
        const result = execSync('gh extension list', { encoding: 'utf-8', stdio: 'pipe' });
        return result.includes('gh-models');
    }
    catch {
        return false;
    }
}
/**
 * Install gh-models extension
 */
export function installGhModels() {
    if (!hasGhCli()) {
        throw new Error('gh CLI is required. Install from https://cli.github.com');
    }
    try {
        execSync('gh extension install github/gh-models', { stdio: 'pipe' });
        return true;
    }
    catch {
        return false;
    }
}
/**
 * Parse a gitgen prompt file (.md) into sections
 */
export function parseGitgenPrompt(content) {
    const lines = content.split('\n');
    let inFrontmatter = false;
    let frontmatterLines = [];
    let currentSection = '';
    const sections = {};
    let sectionContent = [];
    for (const line of lines) {
        if (line.trim() === '---') {
            if (!inFrontmatter && frontmatterLines.length === 0) {
                inFrontmatter = true;
                continue;
            }
            else if (inFrontmatter) {
                inFrontmatter = false;
                continue;
            }
        }
        if (inFrontmatter) {
            frontmatterLines.push(line);
            continue;
        }
        // Check for section header (## sectionName)
        const sectionMatch = line.match(/^## (\w+)/);
        if (sectionMatch) {
            // Save previous section
            if (currentSection) {
                sections[currentSection] = sectionContent.join('\n').trim();
            }
            currentSection = sectionMatch[1];
            sectionContent = [];
            continue;
        }
        if (currentSection) {
            sectionContent.push(line);
        }
    }
    // Save last section
    if (currentSection) {
        sections[currentSection] = sectionContent.join('\n').trim();
    }
    // Parse frontmatter as simple YAML
    const frontmatter = {};
    for (const line of frontmatterLines) {
        const match = line.match(/^(\w+):\s*(.*)$/);
        if (match) {
            const [, key, value] = match;
            // Handle arrays like [alias1, alias2]
            if (value.startsWith('[') && value.endsWith(']')) {
                frontmatter[key] = value
                    .slice(1, -1)
                    .split(',')
                    .map(s => s.trim());
            }
            else {
                frontmatter[key] = value;
            }
        }
    }
    return { frontmatter, sections };
}
/**
 * Convert gitgen prompt to .prompt.yml format
 */
export function toPromptYml(name, description, systemPrompt, userPrompt, options = {}) {
    return {
        name: `gitgen/${name}`,
        description,
        model: options.model || 'openai/gpt-4o',
        modelParameters: {
            temperature: options.temperature ?? 0.7,
            maxTokens: options.maxTokens ?? 4000,
        },
        messages: [
            { role: 'system', content: systemPrompt },
            { role: 'user', content: userPrompt },
        ],
        testData: options.testData,
        evaluators: [
            {
                name: 'has-content',
                string: { contains: '{{' }, // Placeholder - will be replaced
            },
        ],
    };
}
/**
 * Export a gitgen prompt file to .prompt.yml format
 */
export function exportPrompt(promptPath, outputPath, options = {}) {
    const content = readFileSync(promptPath, 'utf-8');
    const { frontmatter, sections } = parseGitgenPrompt(content);
    const section = options.section || 'plan';
    const sectionContent = sections[section];
    if (!sectionContent) {
        throw new Error(`Section '${section}' not found in prompt file`);
    }
    // Split section into system prompt and user prompt
    // Convention: everything before "OUTPUT FORMAT:" is system, after is implicit
    const parts = sectionContent.split(/Begin (?:JSON )?output immediately:/i);
    const systemPrompt = parts[0].trim();
    const userPrompt = 'Execute the task described above.';
    const promptYml = toPromptYml(frontmatter.name || 'unnamed', frontmatter.description || '', systemPrompt, userPrompt, { model: options.model });
    // Convert to YAML string
    const yaml = toYamlString(promptYml);
    // Ensure output directory exists
    const dir = dirname(outputPath);
    if (!existsSync(dir)) {
        mkdirSync(dir, { recursive: true });
    }
    writeFileSync(outputPath, yaml);
}
/**
 * Convert object to YAML string (simple implementation)
 */
function toYamlString(obj) {
    const lines = [];
    lines.push(`name: ${obj.name}`);
    lines.push(`description: ${obj.description}`);
    lines.push(`model: ${obj.model}`);
    if (obj.modelParameters) {
        lines.push('modelParameters:');
        if (obj.modelParameters.temperature !== undefined) {
            lines.push(`  temperature: ${obj.modelParameters.temperature}`);
        }
        if (obj.modelParameters.maxTokens !== undefined) {
            lines.push(`  maxTokens: ${obj.modelParameters.maxTokens}`);
        }
