/**
 * Generate a CHANGELOG.md from git history.
 * Groups commits by tags (if available) or by time periods.
 */
export async function generateChangelog(cwd) {
    // Get all tags sorted by date
    const tags = git("tag --sort=-creatordate", cwd).split("\n").filter(Boolean);
    // Get commit history with more detail
    const logFormat = "%H|%s|%an|%ad|%D";
    const commitLog = git(`log --pretty=format:"${logFormat}" --date=short -200`, cwd);
    if (!commitLog) {
        return "# Changelog\n\nNo commit history found.\n";
    }
    // Parse commits
    const commits = commitLog.split("\n").filter(Boolean).map(line => {
        const [hash, subject, author, date, refs] = line.split("|");
        return { hash: hash.slice(0, 7), subject, author, date, refs: refs || "" };
    });
    // Group commits by tag or month
    const sections = [];
    if (tags.length > 0) {
        // Group by tags
        let currentTag = "Unreleased";
        let currentCommits = [];
        for (const commit of commits) {
            // Check if this commit has a tag
            const tagMatch = commit.refs.match(/tag:\s*([^,)]+)/);
            if (tagMatch) {
                if (currentCommits.length > 0) {
                    sections.push({ title: currentTag, commits: currentCommits });
                }
                currentTag = tagMatch[1].trim();
                currentCommits = [];
            }
            currentCommits.push(commit);
        }
        if (currentCommits.length > 0) {
            sections.push({ title: currentTag, commits: currentCommits });
        }
    }
    else {
        // Group by month
        const byMonth = new Map();
        for (const commit of commits) {
            const month = commit.date.slice(0, 7); // YYYY-MM
            if (!byMonth.has(month)) {
                byMonth.set(month, []);
            }
            byMonth.get(month).push(commit);
        }
        for (const [month, monthCommits] of byMonth) {
            sections.push({ title: month, commits: monthCommits });
        }
    }
    // Build changelog using LLM to summarize
    const template = await loadPrompt("learn-changelog");
    const rawChangelog = sections.slice(0, 10).map(section => {
        const commitList = section.commits.slice(0, 30).map(c => `- ${c.hash} ${c.subject} (${c.author}, ${c.date})`).join("\n");
        return `## ${section.title}\n\n${commitList}`;
    }).join("\n\n");
    const prompt = renderPrompt(template, {
        rawChangelog,
        projectName: git("rev-parse --show-toplevel", cwd).split("/").pop() || "Project",
    });
    return llm(prompt);
}

