  }
}

/**
 * Parse a gitgen prompt file (.md) into sections
 */
export function parseGitgenPrompt(content: string): {
  frontmatter: Record<string, unknown>
  sections: Record<string, string>
} {
  const lines = content.split('\n')
  let inFrontmatter = false
  let frontmatterLines: string[] = []
  let currentSection = ''
  const sections: Record<string, string> = {}
  let sectionContent: string[] = []

  for (const line of lines) {
    if (line.trim() === '---') {
      if (!inFrontmatter && frontmatterLines.length === 0) {
        inFrontmatter = true
        continue
      } else if (inFrontmatter) {
        inFrontmatter = false
        continue
      }
    }

    if (inFrontmatter) {
      frontmatterLines.push(line)
      continue
    }

    // Check for section header (## sectionName)
    const sectionMatch = line.match(/^## (\w+)/)
    if (sectionMatch) {
      // Save previous section
      if (currentSection) {
        sections[currentSection] = sectionContent.join('\n').trim()
      }
      currentSection = sectionMatch[1]
      sectionContent = []
      continue
    }

    if (currentSection) {
      sectionContent.push(line)
    }
  }

  // Save last section
  if (currentSection) {
    sections[currentSection] = sectionContent.join('\n').trim()
  }

  // Parse frontmatter as simple YAML
  const frontmatter: Record<string, unknown> = {}
  for (const line of frontmatterLines) {
    const match = line.match(/^(\w+):\s*(.*)$/)
    if (match) {
      const [, key, value] = match
      // Handle arrays like [alias1, alias2]
      if (value.startsWith('[') && value.endsWith(']')) {
        frontmatter[key] = value
          .slice(1, -1)
          .split(',')
          .map(s => s.trim())
      } else {
        frontmatter[key] = value
      }
    }
  }

  return { frontmatter, sections }
}

/**
 * Convert gitgen prompt to .prompt.yml format
 */
export function toPromptYml(
  name: string,
  description: string,
  systemPrompt: string,
  userPrompt: string,
  options: {
    model?: string
    temperature?: number
    maxTokens?: number
    testData?: Array<Record<string, string>>
  } = {}
): PromptYml {
  return {
    name: `gitgen/${name}`,
    description,
    model: options.model || 'openai/gpt-4o',
    modelParameters: {
      temperature: options.temperature ?? 0.7,
      maxTokens: options.maxTokens ?? 4000,
    },
    messages: [
      { role: 'system', content: systemPrompt },
      { role: 'user', content: userPrompt },
    ],
    testData: options.testData,
    evaluators: [
      {
        name: 'has-content',
        string: { contains: '{{' }, // Placeholder - will be replaced
      },
    ],
  }
}

/**
 * Export a gitgen prompt file to .prompt.yml format
 */
export function exportPrompt(
  promptPath: string,
  outputPath: string,
  options: {
    model?: string
    section?: string
  } = {}
): void {
  const content = readFileSync(promptPath, 'utf-8')
  const { frontmatter, sections } = parseGitgenPrompt(content)

  const section = options.section || 'plan'
  const sectionContent = sections[section]

  if (!sectionContent) {
    throw new Error(`Section '${section}' not found in prompt file`)
  }

  // Split section into system prompt and user prompt
  // Convention: everything before "OUTPUT FORMAT:" is system, after is implicit
  const parts = sectionContent.split(/Begin (?:JSON )?output immediately:/i)
  const systemPrompt = parts[0].trim()
  const userPrompt = 'Execute the task described above.'

  const promptYml = toPromptYml(
    frontmatter.name as string || 'unnamed',
    frontmatter.description as string || '',
    systemPrompt,
    userPrompt,
    { model: options.model }
  )

  // Convert to YAML string
  const yaml = toYamlString(promptYml)

  // Ensure output directory exists
  const dir = dirname(outputPath)
  if (!existsSync(dir)) {
    mkdirSync(dir, { recursive: true })
  }

  writeFileSync(outputPath, yaml)
}

/**
 * Convert object to YAML string (simple implementation)
 */
function toYamlString(obj: PromptYml): string {
  const lines: string[] = []

  lines.push(`name: ${obj.name}`)
  lines.push(`description: ${obj.description}`)
  lines.push(`model: ${obj.model}`)

  if (obj.modelParameters) {
    lines.push('modelParameters:')
    if (obj.modelParameters.temperature !== undefined) {
      lines.push(`  temperature: ${obj.modelParameters.temperature}`)
    }
    if (obj.modelParameters.maxTokens !== undefined) {
      lines.push(`  maxTokens: ${obj.modelParameters.maxTokens}`)
    }
  }

  lines.push('messages:')
  for (const msg of obj.messages) {
    lines.push(`  - role: ${msg.role}`)
    lines.push(`    content: |`)
    for (const line of msg.content.split('\n')) {
      lines.push(`      ${line}`)
    }
  }

  if (obj.testData && obj.testData.length > 0) {
    lines.push('testData:')
    for (const data of obj.testData) {
      const entries = Object.entries(data)
      if (entries.length > 0) {
        lines.push(`  - ${entries[0][0]}: "${entries[0][1]}"`)
        for (const [key, value] of entries.slice(1)) {
          lines.push(`    ${key}: "${value}"`)
        }
      }
    }
  }

  if (obj.evaluators && obj.evaluators.length > 0) {
    lines.push('evaluators:')
    for (const evaluator of obj.evaluators) {
      lines.push(`  - name: ${evaluator.name}`)
      if (evaluator.string) {
        lines.push(`    string:`)
        lines.push(`      contains: "${evaluator.string.contains}"`)
      }
      if (evaluator.uses) {
        lines.push(`    uses: ${evaluator.uses}`)
      }
    }
  }

  return lines.join('\n') + '\n'
}

/**
 * Run gh models eval on a prompt file
 */
export function evalPrompt(promptPath: string): { success: boolean; output: string } {
  if (!hasGhModels()) {
    return {
      success: false,
      output: 'gh-models not installed. Run: gh extension install github/gh-models',
    }
  }

  try {
    const output = execSync(`gh models eval "${promptPath}"`, {
      encoding: 'utf-8',
      stdio: ['pipe', 'pipe', 'pipe'],
    })
    return { success: true, output }
  } catch (error) {
    const err = error as { stderr?: string; stdout?: string }
    return {
      success: false,
      output: err.stderr || err.stdout || 'Evaluation failed',
    }
  }
}

/**
 * Run gh models generate on a prompt file
 */
export function generateTests(
  promptPath: string,
  options: { effort?: 'min' | 'low' | 'medium' | 'high' } = {}
): { success: boolean; output: string } {
  if (!hasGhModels()) {
    return {
      success: false,
      output: 'gh-models not installed. Run: gh extension install github/gh-models',
    }
  }

  try {
    const effortArg = options.effort ? `--effort ${options.effort}` : ''
    const output = execSync(`gh models generate ${effortArg} "${promptPath}"`, {
      encoding: 'utf-8',
      stdio: ['pipe', 'pipe', 'pipe'],
    })
    return { success: true, output }
  } catch (error) {
    const err = error as { stderr?: string; stdout?: string }
    return {
      success: false,
      output: err.stderr || err.stdout || 'Test generation failed',
    }
  }
}

/**
 * List available models via gh models list
 */
export function listModels(): { success: boolean; models: string[]; output: string } {
  if (!hasGhModels()) {
    return {
      success: false,
      models: [],
      output: 'gh-models not installed. Run: gh extension install github/gh-models',
    }
  }

  try {
    const output = execSync('gh models list', {
      encoding: 'utf-8',
      stdio: ['pipe', 'pipe', 'pipe'],
    })
    const models = output
      .split('\n')
      .slice(1) // Skip header
      .map(line => line.split(/\s+/)[0])
      .filter(Boolean)
    return { success: true, models, output }
  } catch (error) {
    const err = error as { stderr?: string; stdout?: string }
    return {
      success: false,
      models: [],
      output: err.stderr || err.stdout || 'Failed to list models',
    }
  }
}

