/**
 * Git operations module - abstraction layer for git commands
 */

import { execSync } from 'node:child_process';
import { existsSync } from 'node:fs';
import { readFile } from 'node:fs/promises';
import { dirname, basename } from 'node:path';

// RAG imports
import {
  isAvailable as isRagAvailable,
} from './rag/index';
import {
  getRelevantContext as ragGetRelevantContext,
  getRelevantCommits as ragGetRelevantCommits,
  getRelevantContextWithStrategy as ragGetRelevantContextWithStrategy,
  getRelevantCommitsWithStrategy as ragGetRelevantCommitsWithStrategy,
  formatAsXml,
  formatCommitsAsXml,
  formatSummaryAsXml,
} from './rag/relevance';
import type { RagStrategyConfig } from '../core/types.js';

// === Core Git Operations ===

/**
 * Execute a git command and return the output
 */
export function git(cmd: string, cwd?: string): string {
  try {
    return execSync(`git ${cmd}`, {
      encoding: 'utf-8',
      cwd,
      stdio: ['pipe', 'pipe', 'pipe'],
    }).trim();
  } catch {
    return '';
  }
}

/**
 * Execute a git command and throw on error
 */
export function gitOrFail(cmd: string, cwd?: string): string {
  return execSync(`git ${cmd}`, {
    encoding: 'utf-8',
    cwd,
  }).trim();
}

// === Branch Operations ===

/**
 * Check if a branch exists
 */
export function branchExists(name: string, cwd?: string): boolean {
  return git(`rev-parse --verify ${name}`, cwd) !== '';
}

/**
 * Get the current branch name
 */
export function getCurrentBranch(cwd?: string): string {
  return git('branch --show-current', cwd);
}

/**
 * Get the default branch (main or master)
 */
export function getDefaultBranch(cwd?: string): string {
  // Try to get from remote
  const remote = git('remote', cwd);
  if (remote) {
    const ref = git(`symbolic-ref refs/remotes/${remote}/HEAD`, cwd);
    if (ref) {
      return ref.replace(/^refs\/remotes\/[^/]+\//, '');
    }
  }
  // Fallback to checking common names
  if (branchExists('main', cwd)) return 'main';
  if (branchExists('master', cwd)) return 'master';
  return 'main';
}

/**
 * Create and checkout a new branch
 */
export function createBranch(name: string, cwd?: string): void {
  gitOrFail(`checkout -b ${name}`, cwd);
}

/**
 * Checkout an existing branch
 */
export function checkoutBranch(name: string, cwd?: string): void {
  gitOrFail(`checkout ${name}`, cwd);
}

/**
 * Create or checkout a branch
 */
export function ensureBranch(name: string, cwd?: string): boolean {
  const current = getCurrentBranch(cwd);
  if (current === name) {
    return false; // Already on branch
  }
  if (branchExists(name, cwd)) {
    checkoutBranch(name, cwd);
    return false; // Existing branch
  }
  createBranch(name, cwd);
  return true; // New branch
}

// === History Operations ===

/**
 * Get commit history for a file
 */
export function getFileHistory(file: string, limit = 10, cwd?: string): string {
  const log = git(`log -${limit} --pretty=format:"%h %s" -- "${file}"`, cwd);
  if (!log) return '';

  const commits = log.split('\n').filter(Boolean);
  const diffs: string[] = [];

  for (const commit of commits.slice(0, 5)) {
    const hash = commit.split(' ')[0];
    const diff = git(`show ${hash} -- "${file}"`, cwd);
    if (diff) {
      diffs.push(`<commit hash="${hash}">\n${diff}\n</commit>`);
    }
  }

  return diffs.join('\n\n');
}

/**
 * Get recent commit diffs
 */
export function getRecentDiffs(limit = 5, cwd?: string): string {
  const log = git(`log -${limit} --pretty=format:"%h"`, cwd);
  if (!log) return '';

  const hashes = log.split('\n').filter(Boolean);
  const diffs: string[] = [];

  for (const hash of hashes) {
    const subject = git(`log -1 --pretty=format:"%s" ${hash}`, cwd);
    const diff = git(`show ${hash} --stat --patch -U2`, cwd);
    if (diff) {
      const truncated = diff.length > 3000
        ? diff.slice(0, 3000) + '\n... (truncated)'
        : diff;
      diffs.push(`<commit hash="${hash}" subject="${subject}">\n${truncated}\n</commit>`);
    }
  }

  return diffs.join('\n\n');
}

/**
 * Get recent commit messages
 */
export function getRecentCommits(limit = 20, cwd?: string): string {
  return git(`log -${limit} --pretty=format:'%h %s'`, cwd);
}

// === Diff Operations ===

/**
 * Get diff between two branches
 */
export function getBranchDiff(branch: string, baseBranch: string, cwd?: string): string {
  const diff = git(`diff ${baseBranch}...${branch} --stat`, cwd);
  const files = git(`diff ${baseBranch}...${branch} --name-only`, cwd);
  const commits = git(`log ${baseBranch}..${branch} --pretty=format:"%h %s" --no-merges`, cwd);

  return `Branch: ${branch}
Commits:
${commits || '(no commits)'}

Files changed:
${files || '(no files)'}

Diff summary:
${diff || '(no diff)'}`;
}

/**
 * Get staged changes
 */
export function getStagedDiff(cwd?: string): string {
  return git('diff --cached', cwd);
}

/**
 * Get unstaged changes
 */
export function getUnstagedDiff(cwd?: string): string {
  return git('diff', cwd);
}

// === File Operations ===

/**
 * Get list of all tracked files
 */
export function getTrackedFiles(cwd?: string): string[] {
  const files = git('ls-files', cwd);
  return files ? files.split('\n').filter(Boolean) : [];
}

/**
 * Get files changed in working tree
 */
export function getChangedFiles(cwd?: string): string[] {
  const status = git('status --porcelain', cwd);
  return status
    ? status.split('\n')
        .filter(Boolean)
        .map(line => line.slice(3))
    : [];
}

/**
 * Get priority files for project context
 */
export function getProjectContextFiles(allFiles: string[]): string[] {
  const priorityPatterns = [
    /^package\.json$/,
    /^tsconfig\.json$/,
    /^\.env\.example$/,
    /^src\/index\.(ts|js|tsx|jsx)$/,
    /^src\/app\.(ts|js|tsx|jsx)$/,
    /^src\/main\.(ts|js|tsx|jsx)$/,
  ];

  const contextFiles: string[] = [];

  // Add priority files first
  for (const pattern of priorityPatterns) {
    const match = allFiles.find(f => pattern.test(f));
    if (match) contextFiles.push(match);
  }

  // Add a few source files to show patterns (max 5 total)
  const sourceFiles = allFiles.filter(f =>
    /\.(ts|js|tsx|jsx)$/.test(f) &&
    !contextFiles.includes(f) &&
    !f.includes('node_modules') &&
    !f.includes('.test.') &&
    !f.includes('.spec.')
  );

  for (const f of sourceFiles.slice(0, 5 - contextFiles.length)) {
    contextFiles.push(f);
  }

  return contextFiles;
}

/**
 * Find related files to a target path
 */
export function findRelatedFiles(targetPath: string, allFiles: string[]): string[] {
  const dir = dirname(targetPath);
  const ext = targetPath.split('.').pop() || '';

  // Files in same directory or parent
  const related = allFiles.filter(f => {
    const fDir = dirname(f);
    return (fDir === dir || fDir === dirname(dir)) &&
           f !== targetPath &&
           f.endsWith(`.${ext}`);
  });

  // Also look for similar named files
  const baseName = basename(targetPath).replace(/\.[^.]+$/, '');
  const similar = allFiles.filter(f => {
    const fBase = basename(f).replace(/\.[^.]+$/, '');
    return f !== targetPath &&
           f.endsWith(`.${ext}`) &&
           (f.includes(dirname(targetPath).split('/').pop() || '') ||
            fBase.length > 3 && baseName.includes(fBase.slice(0, 3)));
  });

  return [...new Set([...related, ...similar])].slice(0, 3);
}

/**
 * Read files safely with truncation
 */
export async function readFilesSafe(paths: string[], maxSize = 5000): Promise<string> {
  const parts: string[] = [];
  for (const path of paths) {
    if (existsSync(path)) {
      try {
        const content = await readFile(path, 'utf-8');
        const truncated = content.length > maxSize
          ? content.slice(0, maxSize) + '\n... (truncated)'
          : content;
        parts.push(`<file path="${path}">\n${truncated}\n</file>`);
      } catch {
        // Skip unreadable files
      }
    }
  }
  return parts.join('\n\n');
}

// === Status Operations ===

/**
 * Get git status
 */
export function getStatus(cwd?: string): string {
  return git('status', cwd);
}

/**
 * Get git status in porcelain format
 */
export function getStatusPorcelain(cwd?: string): string {
  return git('status --porcelain', cwd);
}

/**
 * Check if working tree is clean
 */
export function isClean(cwd?: string): boolean {
  return getStatusPorcelain(cwd) === '';
}

// === Commit Operations ===

/**
 * Stage files
 */
export function stageFiles(files: string[], cwd?: string): void {
  for (const file of files) {
    gitOrFail(`add "${file}"`, cwd);
  }
}

/**
 * Stage all changes
 */
export function stageAll(cwd?: string): void {
  gitOrFail('add -A', cwd);
}

/**
 * Create a commit
 */
export function commit(message: string, cwd?: string): string {
  return gitOrFail(`commit -m "${message.replace(/"/g, '\\"')}"`, cwd);
}

/**
 * Get the latest commit hash
 */
export function getLatestCommit(cwd?: string): string {
  return git('rev-parse HEAD', cwd);
}

// === Remote Operations ===

/**
 * Push to remote
 */
export function push(remote = 'origin', branch?: string, cwd?: string): void {
  const branchArg = branch || getCurrentBranch(cwd);
  gitOrFail(`push -u ${remote} ${branchArg}`, cwd);
}

/**
 * Check if remote exists
 */
export function remoteExists(name = 'origin', cwd?: string): boolean {
  return git(`remote get-url ${name}`, cwd) !== '';
}

// === RAG Operations (Relevance-based retrieval) ===

/**
 * Get relevant code context for a hint (with fallback to time-based)
 */
export function getRelevantCode(hint: string, cwd?: string): string {
  // Try RAG-based retrieval first
  if (isRagAvailable()) {
    const result = ragGetRelevantContext(hint, cwd);
    if (result.items.length > 0) {
      return formatAsXml(result);
    }
  }

  // Fallback to time-based retrieval
  return getRecentDiffs(5, cwd);
}

/**
 * Get relevant commits for a hint (with fallback to time-based)
 */
export function getRelevantCommitsForHint(hint: string, cwd?: string): string {
  // Try RAG-based retrieval first
  if (isRagAvailable()) {
    const commits = ragGetRelevantCommits(hint, cwd);
    if (commits.length > 0) {
      return formatCommitsAsXml(commits);
    }
  }

  // Fallback to time-based retrieval
  return getRecentCommits(20, cwd);
}

/**
 * Get context summary for debugging/logging
 */
export function getContextSummary(hint: string, cwd?: string): string {
  if (isRagAvailable()) {
    const result = ragGetRelevantContext(hint, cwd);
    return formatSummaryAsXml(result.summary);
  }

  return `<context-summary>
  <query>${hint}</query>
  <files-found>0</files-found>
  <commits-analyzed>0</commits-analyzed>
  <relevance-strategy>time-based-fallback</relevance-strategy>
</context-summary>`;
}

/**
 * Get full relevance context (code + commits + summary)
 */
export interface FullRelevanceContext {
  relevantCode: string;
  relevantCommits: string;
  contextSummary: string;
  usingRag: boolean;
}

export function getFullRelevanceContext(hint: string, cwd?: string): FullRelevanceContext {
  const usingRag = isRagAvailable();

  if (usingRag) {
    const result = ragGetRelevantContext(hint, cwd);
    const commits = ragGetRelevantCommits(hint, cwd);

    return {
      relevantCode: formatAsXml(result),
      relevantCommits: formatCommitsAsXml(commits),
      contextSummary: formatSummaryAsXml(result.summary),
      usingRag: result.items.length > 0,
    };
  }

  // Fallback
  return {
    relevantCode: getRecentDiffs(5, cwd),
    relevantCommits: getRecentCommits(20, cwd),
    contextSummary: `<context-summary>
  <query>${hint}</query>
  <files-found>0</files-found>
  <commits-analyzed>0</commits-analyzed>
  <relevance-strategy>time-based-fallback</relevance-strategy>
</context-summary>`,
    usingRag: false,
  };
}

/**
 * Get full relevance context with prompt type strategy applied
 */
export function getFullRelevanceContextWithType(
  hint: string,
  strategy: RagStrategyConfig,
  cwd?: string
): FullRelevanceContext {
  const usingRag = isRagAvailable();

  if (usingRag) {
    const result = ragGetRelevantContextWithStrategy(hint, strategy, cwd);
    const commits = ragGetRelevantCommitsWithStrategy(hint, strategy, cwd);

    return {
      relevantCode: formatAsXml(result),
      relevantCommits: formatCommitsAsXml(commits),
      contextSummary: formatSummaryAsXml(result.summary),
      usingRag: result.items.length > 0,
    };
  }

  // Fallback to time-based
  return {
    relevantCode: getRecentDiffs(5, cwd),
    relevantCommits: getRecentCommits(20, cwd),
    contextSummary: `<context-summary>
  <query>${hint}</query>
  <files-found>0</files-found>
  <commits-analyzed>0</commits-analyzed>
  <relevance-strategy>time-based-fallback</relevance-strategy>
</context-summary>`,
    usingRag: false,
  };
}

import { execSync } from "node:child_process";
import { readFile } from "node:fs/promises";
import { existsSync } from "node:fs";
import { join } from "node:path";
import { llm } from "../providers/index.js";
import { loadPrompt as loadPromptFromCommands } from "../prompts/index.js";

export interface CommitInfo {
  hash: string;
  subject: string;
  files: string[];
  diff?: string;
}

export interface ConventionInfo {
  commitStyle: string;
  namingPatterns: string[];
  directoryPatterns: string[];
}

export interface FileInfo {
  path: string;
  content: string;
}

export interface RepoAnalysis {
  recentCommits: CommitInfo[];
  fileStructure: string[];
  conventions: ConventionInfo;
  techStack: string[];
  keyFiles: FileInfo[];
}

/**
 * Execute a git command and return the output.
 */
function git(cmd: string, cwd?: string): string {
  try {
    return execSync(`git ${cmd}`, { encoding: "utf-8", cwd }).trim();
  } catch {
    return "";
  }
}

/**
 * Get recent commits with file changes.
 */
function getRecentCommits(limit: number, cwd?: string): CommitInfo[] {
  const log = git(`log -${limit} --pretty=format:"%h|%s"`, cwd);
  const commits: CommitInfo[] = [];

  for (const line of log.split("\n").filter(Boolean)) {
    const [hash, subject] = line.split("|");
    const files = git(`diff-tree --no-commit-id --name-only -r ${hash}`, cwd)
      .split("\n")
      .filter(Boolean);

    commits.push({ hash, subject, files });
  }

  // Get diffs for recent commits (limit to avoid token explosion)
  for (const commit of commits.slice(0, 10)) {
    const diff = git(`show ${commit.hash} --stat -p -U2`, cwd);
    if (diff) {
      // Truncate large diffs
      commit.diff = diff.length > 3000 ? diff.slice(0, 3000) + "\n... (truncated)" : diff;
    }
  }

  return commits;
}

/**
 * Detect tech stack from file extensions and config files.
 */
function detectTechStack(files: string[]): string[] {
  const stack: string[] = [];

  if (files.some((f) => f === "package.json")) stack.push("node");
  if (files.some((f) => f.endsWith(".ts") || f.endsWith(".tsx"))) stack.push("typescript");
  if (files.some((f) => f.endsWith(".jsx") || f.endsWith(".tsx"))) stack.push("react");
  if (files.some((f) => f === "next.config.js" || f === "next.config.mjs" || f === "next.config.ts"))
    stack.push("nextjs");
  if (files.some((f) => f === "vite.config.ts" || f === "vite.config.js")) stack.push("vite");
  if (files.some((f) => f === "requirements.txt" || f === "pyproject.toml")) stack.push("python");
  if (files.some((f) => f === "go.mod")) stack.push("go");
  if (files.some((f) => f === "Cargo.toml")) stack.push("rust");
  if (files.some((f) => f === "Gemfile")) stack.push("ruby");
  if (files.some((f) => f === "pom.xml" || f === "build.gradle")) stack.push("java");
  if (files.some((f) => f.endsWith(".vue"))) stack.push("vue");
  if (files.some((f) => f.endsWith(".svelte"))) stack.push("svelte");
  if (files.some((f) => f === "tailwind.config.js" || f === "tailwind.config.ts"))
    stack.push("tailwind");

  return stack;
}

/**
 * Analyze naming and directory conventions from commits and files.
 */
function analyzeConventions(commits: CommitInfo[], files: string[]): ConventionInfo {
  // Detect commit message style
  const subjects = commits.map((c) => c.subject);
  let commitStyle = "freeform";

  const conventionalCount = subjects.filter((s) =>
    /^(feat|fix|docs|style|refactor|test|chore|perf|ci|build|revert)(\(.+\))?:/.test(s)
  ).length;
  const bracketedCount = subjects.filter((s) => /^\[.+\]/.test(s)).length;

  if (conventionalCount > subjects.length * 0.5) {
    commitStyle = "conventional";
  } else if (bracketedCount > subjects.length * 0.3) {
    commitStyle = "bracketed";
  }

  // Detect naming patterns
  const namingPatterns: string[] = [];
  const tsFiles = files.filter((f) => f.endsWith(".ts") || f.endsWith(".tsx"));
  const jsFiles = files.filter((f) => f.endsWith(".js") || f.endsWith(".jsx"));
  const codeFiles = [...tsFiles, ...jsFiles];

  if (codeFiles.some((f) => /[A-Z][a-z]+\.(tsx?|jsx?)$/.test(f))) {
    namingPatterns.push("PascalCase for components");
  }
  if (codeFiles.some((f) => /[a-z]+-[a-z]+\.(tsx?|jsx?)$/.test(f))) {
    namingPatterns.push("kebab-case for files");
  }
  if (codeFiles.some((f) => /[a-z]+[A-Z][a-z]+\.(tsx?|jsx?)$/.test(f))) {
    namingPatterns.push("camelCase for files");
  }
  if (codeFiles.some((f) => /[a-z]+_[a-z]+\.(tsx?|jsx?)$/.test(f))) {
    namingPatterns.push("snake_case for files");
  }

  // Detect directory patterns
  const directoryPatterns: string[] = [];
  const dirs = [...new Set(files.map((f) => f.split("/")[0]))];

  if (dirs.includes("src")) directoryPatterns.push("src/ for source code");
  if (dirs.includes("lib")) directoryPatterns.push("lib/ for libraries");
  if (dirs.includes("utils") || files.some((f) => f.includes("/utils/")))
    directoryPatterns.push("utils/ for utilities");
  if (dirs.includes("components") || files.some((f) => f.includes("/components/")))
    directoryPatterns.push("components/ for UI components");
  if (dirs.includes("pages") || files.some((f) => f.includes("/pages/")))
    directoryPatterns.push("pages/ for routes");
  if (dirs.includes("app") || files.some((f) => f.includes("/app/")))
    directoryPatterns.push("app/ for Next.js app router");
  if (dirs.includes("tests") || dirs.includes("test") || dirs.includes("__tests__"))
    directoryPatterns.push("tests/ for test files");
  if (dirs.includes("hooks") || files.some((f) => f.includes("/hooks/")))
    directoryPatterns.push("hooks/ for React hooks");
  if (dirs.includes("api") || files.some((f) => f.includes("/api/")))
    directoryPatterns.push("api/ for API routes");

  return { commitStyle, namingPatterns, directoryPatterns };
}

/**
 * Read key configuration and documentation files.
 */
async function readKeyFiles(files: string[], cwd?: string): Promise<FileInfo[]> {
  const keyFilePatterns = [
    "package.json",
    "tsconfig.json",
    ".eslintrc.json",
    ".eslintrc.js",
    "eslint.config.js",
    ".prettierrc",
    ".prettierrc.json",
    "README.md",
    "CONTRIBUTING.md",
  ];

  const keyFiles: FileInfo[] = [];

  for (const pattern of keyFilePatterns) {
    const match = files.find((f) => f.endsWith(pattern));
    if (match) {
      const fullPath = cwd ? join(cwd, match) : match;
      if (existsSync(fullPath)) {
        try {
          const content = await readFile(fullPath, "utf-8");
          // Truncate large files
          keyFiles.push({
            path: match,
            content: content.length > 2000 ? content.slice(0, 2000) + "\n... (truncated)" : content,
          });
        } catch {
          // Skip unreadable files
        }
      }
    }
  }

  return keyFiles;
}

/**
 * Analyze the repository to understand its patterns and conventions.
 */
export async function analyzeRepo(depth: number = 50, cwd?: string): Promise<RepoAnalysis> {
  // Get recent commits with context
  const commits = getRecentCommits(depth, cwd);

  // Analyze file structure
  const files = git("ls-files", cwd).split("\n").filter(Boolean);

  // Detect tech stack from files
  const techStack = detectTechStack(files);

  // Analyze naming and directory conventions
  const conventions = analyzeConventions(commits, files);

  // Read key configuration files
  const keyFiles = await readKeyFiles(files, cwd);

  return {
    recentCommits: commits,
    fileStructure: files,
    conventions,
    techStack,
    keyFiles,
  };
}

/**
 * Render a prompt template with variables.
 */
function renderPrompt(template: string, vars: Record<string, string | undefined>): string {
  let result = template;

  // Handle conditionals: {{#var}}content{{/var}}
  for (const [key, value] of Object.entries(vars)) {
    const conditionalPattern = new RegExp(`\\{\\{#${key}\\}\\}([\\s\\S]*?)\\{\\{/${key}\\}\\}`, "g");
    if (value) {
      result = result.replace(conditionalPattern, "$1");
    } else {
      result = result.replace(conditionalPattern, "");
    }
  }

  // Handle simple substitutions: {{var}}
  for (const [key, value] of Object.entries(vars)) {
    result = result.replace(new RegExp(`\\{\\{${key}\\}\\}`, "g"), value || "");
  }

  return result.trim();
}

/**
 * Load a prompt template from .agent/commands directory.
 */
async function loadPrompt(name: string): Promise<string> {
  return loadPromptFromCommands(name);
}

/**
 * Generate a .gitgen.md specification for the repository.
 *
 * @param customPrompt - Optional additional focus/instructions
 * @param refContext - Optional existing .gitgen.md from another ref to use as reference
 * @param sourceRepoPath - Optional path to external repo to analyze (for GitHub repos/PRs)
 * @param issueContext - Optional issue context for focused learning
 */
export async function generateProjectSpec(
  customPrompt?: string,
  refContext?: string,
  sourceRepoPath?: string,
  issueContext?: string
): Promise<string> {
  // Analyze the source repo if provided, otherwise analyze current repo
  const analysis = await analyzeRepo(50, sourceRepoPath);
  // Load synthesize section which produces .gitgen.md format
  const template = await loadPrompt("learn-synthesize");

  let prompt = renderPrompt(template, {
    techStack: analysis.techStack.join(", ") || "not detected",
    commitStyle: analysis.conventions.commitStyle,
    namingPatterns: analysis.conventions.namingPatterns.join("\n") || "not detected",
    directoryPatterns: analysis.conventions.directoryPatterns.join("\n") || "not detected",
    recentCommits: analysis.recentCommits
      .slice(0, 20)
      .map((c) => `${c.hash} ${c.subject}`)
      .join("\n"),
    recentDiffs: analysis.recentCommits
      .slice(0, 5)
      .map((c) => c.diff)
      .filter(Boolean)
      .join("\n\n"),
    keyFiles: analysis.keyFiles
      .map((f) => `<file path="${f.path}">\n${f.content}\n</file>`)
      .join("\n\n"),
    fileStructure: analysis.fileStructure.slice(0, 100).join("\n"),
    issueContext,
  });

  // If we have context from another ref, include it as reference
  if (refContext) {
    prompt += `\n\nREFERENCE SPEC (from another branch/tag):\nUse this as a foundation and update based on current analysis:\n\n${refContext}`;
  }

  if (customPrompt) {
    prompt += `\n\nADDITIONAL FOCUS:\n${customPrompt}`;
  }

  const result = await llm(prompt);

  // Fix common YAML formatting issues from LLMs
  // Fix "  -./file" or "  -../file" to "  - ./file" (missing space after dash)
  return result.replace(/^(\s*)-(\..*)$/gm, "$1- $2");
}

/**
 * Generate a focused deep-dive document for a specific topic.
 *
 * @param topic - The topic to focus on (e.g., "plugin development", "auth system")
 * @param sourceRepoPath - Optional path to external repo to analyze
 * @param issueContext - Optional issue context for focused learning
 */
export async function generateFocusedContext(
  topic: string,
  sourceRepoPath?: string,
  issueContext?: string
): Promise<string> {
  // Deep analysis for focused context (200 commits)
  const analysis = await analyzeRepo(200, sourceRepoPath);
  const template = await loadPrompt("learn-focus");

  const prompt = renderPrompt(template, {
    focusTopic: topic,
    techStack: analysis.techStack.join(", ") || "not detected",
    recentDiffs: analysis.recentCommits
      .slice(0, 20) // More diffs for deep analysis
      .map((c) => c.diff)
      .filter(Boolean)
      .join("\n\n"),
    keyFiles: analysis.keyFiles
      .map((f) => `<file path="${f.path}">\n${f.content}\n</file>`)
      .join("\n\n"),
    fileStructure: analysis.fileStructure.slice(0, 200).join("\n"), // More files
    issueContext,
  });

  return llm(prompt);
}

/**
 * Convert a topic string to a valid filename slug.
 * e.g., "plugin development" -> "plugin-development"
 */
export function topicToSlug(topic: string): string {
  return topic
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-|-$/g, '')
    .slice(0, 50); // Limit length
}

/**
 * Get a summary of the repository analysis.
 */
export async function getRepoSummary(): Promise<string> {
  const analysis = await analyzeRepo(20);

  const lines = [
    `Tech stack: ${analysis.techStack.join(", ") || "not detected"}`,
    `Commit style: ${analysis.conventions.commitStyle}`,
    `Files: ${analysis.fileStructure.length}`,
    `Recent commits: ${analysis.recentCommits.length}`,
  ];

  if (analysis.conventions.namingPatterns.length > 0) {
    lines.push(`Naming: ${analysis.conventions.namingPatterns.join(", ")}`);
  }

  if (analysis.conventions.directoryPatterns.length > 0) {
    lines.push(`Structure: ${analysis.conventions.directoryPatterns.join(", ")}`);
  }

  return lines.join("\n");
}

/**
 * Generate a CHANGELOG.md from git history.
 * Groups commits by tags (if available) or by time periods.
 */
export async function generateChangelog(cwd?: string): Promise<string> {
  // Get all tags sorted by date
  const tags = git("tag --sort=-creatordate", cwd).split("\n").filter(Boolean);

  // Get commit history with more detail
  const logFormat = "%H|%s|%an|%ad|%D";
  const commitLog = git(`log --pretty=format:"${logFormat}" --date=short -200`, cwd);

  if (!commitLog) {
    return "# Changelog\n\nNo commit history found.\n";
  }

  // Parse commits
  const commits = commitLog.split("\n").filter(Boolean).map(line => {
    const [hash, subject, author, date, refs] = line.split("|");
    return { hash: hash.slice(0, 7), subject, author, date, refs: refs || "" };
  });

  // Group commits by tag or month
  const sections: Array<{ title: string; commits: typeof commits }> = [];

  if (tags.length > 0) {
    // Group by tags
    let currentTag = "Unreleased";
    let currentCommits: typeof commits = [];

    for (const commit of commits) {
      // Check if this commit has a tag
      const tagMatch = commit.refs.match(/tag:\s*([^,)]+)/);
      if (tagMatch) {
        if (currentCommits.length > 0) {
          sections.push({ title: currentTag, commits: currentCommits });
        }
        currentTag = tagMatch[1].trim();
        currentCommits = [];
      }
      currentCommits.push(commit);
    }

    if (currentCommits.length > 0) {
      sections.push({ title: currentTag, commits: currentCommits });
    }
  } else {
    // Group by month
    const byMonth = new Map<string, typeof commits>();
    for (const commit of commits) {
      const month = commit.date.slice(0, 7); // YYYY-MM
      if (!byMonth.has(month)) {
        byMonth.set(month, []);
      }
      byMonth.get(month)!.push(commit);
    }

    for (const [month, monthCommits] of byMonth) {
      sections.push({ title: month, commits: monthCommits });
    }
  }

  // Build changelog using LLM to summarize
  const template = await loadPrompt("learn-changelog");

  const rawChangelog = sections.slice(0, 10).map(section => {
    const commitList = section.commits.slice(0, 30).map(c =>
      `- ${c.hash} ${c.subject} (${c.author}, ${c.date})`
    ).join("\n");
    return `## ${section.title}\n\n${commitList}`;
  }).join("\n\n");

  const prompt = renderPrompt(template, {
    rawChangelog,
    projectName: git("rev-parse --show-toplevel", cwd).split("/").pop() || "Project",
  });

  return llm(prompt);
}

