/**
 * Prompt loading and rendering module
 *
 * Commands are stored in .agent/commands/gitgen/ as markdown files with:
 * - YAML frontmatter (name, description, aliases)
 * - Bash block for CLI invocation (Claude Code / Gemini CLI)
 * - ## plan section for planning phase
 * - ## file section for file generation phase
 *
 * Loading:
 * - loadPrompt('feature') → loads full file
 * - loadPrompt('feature-plan') → extracts ## plan section from feature.md
 * - loadPrompt('feature-file') → extracts ## file section from feature.md
 *
 * Schema references:
 * - {{schema:intent}} → injects content from .agent/schemas/intent.schema.md
 * - {{schema:plan}} → injects content from .agent/schemas/plan.schema.md
 */

import { readFile } from 'node:fs/promises';
import { existsSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

// Get the commands directory path (.agent/commands/gitgen/)
const __dirname = dirname(fileURLToPath(import.meta.url));
const COMMANDS_DIR = join(__dirname, '..', '..', '.agent', 'commands', 'gitgen');
const SCHEMAS_DIR = join(__dirname, '..', '..', '.agent', 'schemas');

// Cache for loaded prompts and schemas
const promptCache = new Map<string, string>();
const schemaCache = new Map<string, string>();

/**
 * Load a schema by name
 * Schemas are stored in .agent/schemas/{name}.schema.md
 */
async function loadSchema(name: string): Promise<string> {
  // Check cache first
  if (schemaCache.has(name)) {
    return schemaCache.get(name)!;
  }

  const schemaPath = join(SCHEMAS_DIR, `${name}.schema.md`);
  if (!existsSync(schemaPath)) {
    throw new Error(`Schema not found: ${name}`);
  }

  const content = await readFile(schemaPath, 'utf-8');

  // Extract just the JSON Schema section for inline embedding
  // Look for ```json block within ## JSON Schema section
  const jsonSchemaMatch = content.match(/## JSON Schema\s*\n\s*```json\s*\n([\s\S]*?)```/);
  const schemaContent = jsonSchemaMatch
    ? jsonSchemaMatch[1].trim()
    : content; // Fallback to full content if no JSON Schema section

  schemaCache.set(name, schemaContent);
  return schemaContent;
}

/**
 * Extract a section from markdown content
 * Looks for ## sectionName and returns content until next ## or end
 */
function extractSection(content: string, sectionName: string): string | null {
  // Find the section header
  const headerRegex = new RegExp(`^## ${sectionName}\\s*$`, 'mi');
  const headerMatch = content.match(headerRegex);
  if (!headerMatch || headerMatch.index === undefined) return null;

  // Extract from after header to next ## or end of string
  const startIndex = headerMatch.index + headerMatch[0].length;
  const rest = content.slice(startIndex);

  // Find next ## header (at start of line)
  const nextHeaderMatch = rest.match(/^## /m);
  const sectionContent = nextHeaderMatch?.index !== undefined
    ? rest.slice(0, nextHeaderMatch.index)
    : rest;

  return sectionContent.trim();
}

/**
 * Parse prompt name to check for section suffix
 * Returns [baseName, section] or [name, null]
 */
function parsePromptName(name: string): [string, string | null] {
  const sectionSuffixes = ['-plan', '-file', '-sql', '-analyze', '-synthesize'];
  for (const suffix of sectionSuffixes) {
    if (name.endsWith(suffix)) {
      const baseName = name.slice(0, -suffix.length);
      const section = suffix.slice(1); // Remove leading dash
      return [baseName, section];
    }
  }
  return [name, null];
}

/**
 * Load a prompt template by name
 *
 * Supports consolidated format:
 * - 'feature' → loads feature.md
 * - 'feature-plan' → loads feature.md, extracts ## plan section
 * - 'feature-file' → loads feature.md, extracts ## file section
 */
export async function loadPrompt(name: string, customDir?: string): Promise<string> {
  // Check cache first
  const cacheKey = `${customDir || 'default'}:${name}`;
  if (promptCache.has(cacheKey)) {
    return promptCache.get(cacheKey)!;
  }

  const [baseName, section] = parsePromptName(name);

  // Try custom directory first if provided
  if (customDir) {
    const customPath = join(customDir, `${baseName}.md`);
    if (existsSync(customPath)) {
      const content = await readFile(customPath, 'utf-8');
      const result = section ? extractSection(content, section) : content;
      if (result) {
        promptCache.set(cacheKey, result);
        return result;
      }
    }
  }

  // Load from .agent/commands/gitgen directory
  const promptPath = join(COMMANDS_DIR, `${baseName}.md`);
  if (!existsSync(promptPath)) {
    throw new Error(`Prompt not found: ${name}`);
  }

  const content = await readFile(promptPath, 'utf-8');

  // Extract section if requested
  if (section) {
    const sectionContent = extractSection(content, section);
    if (!sectionContent) {
      throw new Error(`Section '${section}' not found in ${baseName}.md`);
    }
    promptCache.set(cacheKey, sectionContent);
    return sectionContent;
  }

  promptCache.set(cacheKey, content);
  return content;
}

/**
 * Render a prompt template with variables
 *
 * Supports:
 * - Simple substitution: {{var}}
 * - Conditionals: {{#var}}content{{/var}}
 * - Schema references: {{schema:name}} (requires async rendering)
 */
export function renderPrompt(
  template: string,
  vars: Record<string, string | undefined>
): string {
  let result = template;

  // Handle conditionals: {{#var}}content{{/var}}
  for (const [key, value] of Object.entries(vars)) {
    const conditionalPattern = new RegExp(
      `\\{\\{#${key}\\}\\}([\\s\\S]*?)\\{\\{/${key}\\}\\}`,
      'g'
    );
    result = result.replace(conditionalPattern, value ? '$1' : '');
  }

  // Handle simple substitutions: {{var}}
  for (const [key, value] of Object.entries(vars)) {
    result = result.replaceAll(`{{${key}}}`, value || '');
  }

  return result.trim();
}

/**
 * Render a prompt template with variables, including async schema loading
 *
 * Supports:
 * - Simple substitution: {{var}}
 * - Conditionals: {{#var}}content{{/var}}
 * - Schema references: {{schema:name}}
 */
export async function renderPromptAsync(
  template: string,
  vars: Record<string, string | undefined>
): Promise<string> {
  let result = template;

  // Handle schema references: {{schema:name}}
  const schemaPattern = /\{\{schema:(\w+)\}\}/g;
  const schemaMatches = [...result.matchAll(schemaPattern)];

  for (const match of schemaMatches) {
    const schemaName = match[1];
    try {
      const schemaContent = await loadSchema(schemaName);
      result = result.replace(match[0], schemaContent);
    } catch (error) {
      // Leave placeholder if schema not found
      console.error(`Warning: Schema '${schemaName}' not found`);
    }
  }

  // Handle conditionals: {{#var}}content{{/var}}
  for (const [key, value] of Object.entries(vars)) {
    const conditionalPattern = new RegExp(
      `\\{\\{#${key}\\}\\}([\\s\\S]*?)\\{\\{/${key}\\}\\}`,
      'g'
    );
    result = result.replace(conditionalPattern, value ? '$1' : '');
  }

  // Handle simple substitutions: {{var}}
  for (const [key, value] of Object.entries(vars)) {
    result = result.replaceAll(`{{${key}}}`, value || '');
  }

  return result.trim();
}

/**
 * Clear the prompt and schema caches
 */
export function clearPromptCache(): void {
  promptCache.clear();
  schemaCache.clear();
}

/**
 * Preload commonly used prompts
 */
export async function preloadPrompts(): Promise<void> {
  const commonPrompts = [
    'learn',
    'generate',
    'init',
    // Consolidated type-specific templates (will load sections)
    'feature-plan',
    'feature-file',
    'feature-analyze',
    'fix-plan',
    'fix-file',
    'fix-analyze',
    'refactor-plan',
    'refactor-file',
    'test-plan',
    'test-file',
    'plan-plan',
    'plan-file',
    // Ask command sections
    'ask-analyze',
    'ask-sql',
    'ask-synthesize',
  ];

  await Promise.all(commonPrompts.map(name => loadPrompt(name).catch(() => null)));
}

/**
 * Get all available prompt names
 */
export async function getAvailablePrompts(): Promise<string[]> {
  const { readdir } = await import('node:fs/promises');

  try {
    const files = await readdir(COMMANDS_DIR);
    return files
      .filter(f => f.endsWith('.md'))
      .map(f => f.replace('.md', ''));
  } catch {
    return [];
  }
}

/**
 * Create a prompt loader with custom overrides
 */
export function createPromptLoader(overrides?: Map<string, string>) {
  return {
    async load(name: string): Promise<string> {
      if (overrides?.has(name)) {
        return overrides.get(name)!;
      }
      return loadPrompt(name);
    },

    render: renderPrompt,

    setOverride(name: string, content: string): void {
      overrides?.set(name, content);
    },

    clearOverride(name: string): void {
      overrides?.delete(name);
    },
  };
}

import { anthropic } from "@ai-sdk/anthropic";
import { bedrock } from "@ai-sdk/amazon-bedrock";
import { createOpenRouter } from "@openrouter/ai-sdk-provider";
import { openai } from "@ai-sdk/openai";
import { google } from "@ai-sdk/google";
import { generateText } from "ai";
import { existsSync, readFileSync } from "fs";
import { homedir } from "os";
import { join } from "path";

/**
 * Load AWS credentials from ~/.aws/credentials and ~/.aws/config files.
 * Sets them as environment variables if not already set.
 */
function loadAwsCredentialsFromFile(): void {
  const profile = process.env.AWS_PROFILE || "default";

  // Load credentials file
  const credentialsPath = join(homedir(), ".aws", "credentials");
  if (existsSync(credentialsPath)) {
    const content = readFileSync(credentialsPath, "utf-8");
    const credentials = parseIniFile(content, profile);
    if (credentials.aws_access_key_id && !process.env.AWS_ACCESS_KEY_ID) {
      process.env.AWS_ACCESS_KEY_ID = credentials.aws_access_key_id;
    }
    if (credentials.aws_secret_access_key && !process.env.AWS_SECRET_ACCESS_KEY) {
      process.env.AWS_SECRET_ACCESS_KEY = credentials.aws_secret_access_key;
    }
  }

  // Force us-east-1 for Bedrock cross-region inference profiles
  // The us.anthropic.* inference profile IDs require the SDK to connect to us-east-1
  if (!process.env.AWS_REGION) {
    process.env.AWS_REGION = "us-east-1";
  }
}

/**
 * Parse an INI file and return values for a specific profile.
 */
function parseIniFile(content: string, profile: string): Record<string, string> {
  const result: Record<string, string> = {};
  const lines = content.split("\n");
  let inProfile = false;

  for (const line of lines) {
    const trimmed = line.trim();
    if (trimmed.startsWith("[") && trimmed.endsWith("]")) {
      const sectionName = trimmed.slice(1, -1);
      inProfile = sectionName === profile;
    } else if (inProfile && trimmed.includes("=")) {
      const [key, ...valueParts] = trimmed.split("=");
      result[key.trim()] = valueParts.join("=").trim();
    }
  }

  return result;
}

export type ProviderType = "anthropic" | "bedrock" | "openrouter" | "openai" | "google";

export interface ProviderConfig {
  provider: ProviderType;
}

export interface LLMResult {
  text: string;
  usage?: {
    promptTokens: number;
    completionTokens: number;
  };
}

/**
 * LLM provider function signature.
 * Allows injection of custom LLM providers (e.g., OpenCode).
 */
export type LLMProvider = (prompt: string) => Promise<string>;

// Injected provider (null = use default providers)
let injectedProvider: LLMProvider | null = null;

/**
 * Set a custom LLM provider.
 * When set, all llm() calls will use this provider instead of the default.
 */
export function setLLMProvider(provider: LLMProvider): void {
  injectedProvider = provider;
}

/**
 * Clear the injected LLM provider, reverting to default behavior.
 */
export function clearLLMProvider(): void {
  injectedProvider = null;
}

// Model mappings per provider
const MODEL_MAPPINGS: Record<ProviderType, Record<string, string>> = {
  anthropic: {
    default: "claude-sonnet-4-20250514",
    "claude-sonnet": "claude-sonnet-4-20250514",
    "claude-opus": "claude-opus-4-20250514",
    "claude-haiku": "claude-3-5-haiku-20241022",
  },
  bedrock: {
    default: "us.anthropic.claude-opus-4-5-20251101-v1:0",
    "claude-sonnet": "us.anthropic.claude-3-5-sonnet-20241022-v2:0",
    "claude-opus": "us.anthropic.claude-opus-4-5-20251101-v1:0",
    "claude-haiku": "us.anthropic.claude-3-5-haiku-20241022-v1:0",
  },
  openai: {
    default: "gpt-4o",
    "gpt-4o": "gpt-4o",
    "gpt-4o-mini": "gpt-4o-mini",
    "gpt-4-turbo": "gpt-4-turbo",
    "o1": "o1",
    "o1-mini": "o1-mini",
  },
  google: {
    default: "gemini-2.0-flash",
    "gemini-flash": "gemini-2.0-flash",
    "gemini-pro": "gemini-1.5-pro",
    "gemini-2.0-flash": "gemini-2.0-flash",
    "gemini-1.5-pro": "gemini-1.5-pro",
  },
  openrouter: {
    default: "meta-llama/llama-3.3-70b-instruct:free",
    "gemini": "google/gemini-2.0-flash-exp:free",
    "llama": "meta-llama/llama-3.3-70b-instruct:free",
    "qwen": "qwen/qwen-2.5-72b-instruct:free",
  },
};

const MAX_TOKENS = 8192;

/**
 * Check if AWS credentials are available (env vars or credentials file).
 * If found in file, loads them into environment variables.
 */
function hasAwsCredentials(): boolean {
  if (process.env.AWS_ACCESS_KEY_ID && process.env.AWS_REGION) {
    return true;
  }
  // Check for AWS credentials file
  const credentialsPath = join(homedir(), ".aws", "credentials");
  if (existsSync(credentialsPath)) {
    loadAwsCredentialsFromFile();
    return true;
  }
  return false;
}

/**
 * Get provider configuration from environment variables.
 * Priority: GITGEN_PROVIDER > auto-detect from available keys
 */
export function getProviderConfig(): ProviderConfig {
  const explicitProvider = process.env.GITGEN_PROVIDER as ProviderType;
  const validProviders: ProviderType[] = ["anthropic", "bedrock", "openrouter", "openai", "google"];

  if (explicitProvider && validProviders.includes(explicitProvider)) {
    return { provider: explicitProvider };
  }

  // Auto-detect based on available environment variables or credentials file
  if (hasAwsCredentials()) {
    return { provider: "bedrock" };
  }
  if (process.env.ANTHROPIC_API_KEY) {
    return { provider: "anthropic" };
  }
  if (process.env.OPENAI_API_KEY) {
    return { provider: "openai" };
  }
  if (process.env.GOOGLE_GENERATIVE_AI_API_KEY) {
    return { provider: "google" };
  }
  if (process.env.OPENROUTER_API_KEY) {
    return { provider: "openrouter" };
  }

  throw new Error(
    "No provider configured. Set ANTHROPIC_API_KEY, OPENAI_API_KEY, GOOGLE_GENERATIVE_AI_API_KEY, AWS credentials, or OPENROUTER_API_KEY."
  );
}

/**
 * Resolve model alias to full model ID for the given provider.
 */
export function resolveModel(modelAlias: string | undefined, provider: ProviderType): string {
  const mappings = MODEL_MAPPINGS[provider];
  if (!modelAlias) return mappings.default;
  return mappings[modelAlias] || modelAlias; // Allow direct model IDs
}

/**
 * Get the model instance for the configured provider.
 */
// eslint-disable-next-line @typescript-eslint/no-explicit-any
function getModel(modelId: string, provider: ProviderType): any {
  switch (provider) {
    case "anthropic":
      return anthropic(modelId);
    case "bedrock":
      return bedrock(modelId);
    case "openai":
      return openai(modelId);
    case "google":
      return google(modelId);
    case "openrouter":
      const openrouter = createOpenRouter({
        apiKey: process.env.OPENROUTER_API_KEY,
      });
      return openrouter(modelId);
  }
}

/**
 * Strip markdown code fences from content.
 */
function stripCodeFences(content: string): string {
  const fencePattern = /^```[\w]*\n([\s\S]*?)\n```$/;
  const match = content.trim().match(fencePattern);
  return match ? match[1] : content;
}

/**
 * Call the LLM with the given prompt and optional model alias.
 * Uses injected provider if set, otherwise auto-detects from environment.
 */
export async function llm(prompt: string, modelAlias?: string): Promise<string> {
  // Use injected provider if set (e.g., OpenCode)
  if (injectedProvider) {
    const result = await injectedProvider(prompt);
    return stripCodeFences(result);
  }

  // Default: use configured provider
  const config = getProviderConfig();
  const modelId = resolveModel(modelAlias || process.env.GITGEN_MODEL, config.provider);
  const model = getModel(modelId, config.provider);

  const result = await generateText({
    model,
    prompt,
    maxTokens: MAX_TOKENS,
  });

  return stripCodeFences(result.text);
}

/**
 * Call the LLM and return full result including usage stats.
 * Note: Usage stats not available when using injected provider.
 */
export async function llmWithUsage(prompt: string, modelAlias?: string): Promise<LLMResult> {
  // Use injected provider if set (no usage stats available)
  if (injectedProvider) {
    const result = await injectedProvider(prompt);
    return { text: stripCodeFences(result) };
  }

  // Default: use configured provider
  const config = getProviderConfig();
  const modelId = resolveModel(modelAlias || process.env.GITGEN_MODEL, config.provider);
  const model = getModel(modelId, config.provider);

  const result = await generateText({
    model,
    prompt,
    maxTokens: MAX_TOKENS,
  });

  return {
    text: stripCodeFences(result.text),
    usage: result.usage
      ? {
          promptTokens: result.usage.promptTokens,
          completionTokens: result.usage.completionTokens,
        }
      : undefined,
  };
}

/**
 * Get provider status including connection state.
 */
export function getProviderStatus(): { configured: boolean; provider?: string; model?: string } {
  try {
    const config = getProviderConfig();
    const modelId = resolveModel(process.env.GITGEN_MODEL, config.provider);
    return { configured: true, provider: config.provider, model: modelId };
  } catch {
    return { configured: false };
  }
}

/**
 * Get a human-readable description of the current provider with status indicator.
 */
export function getProviderDescription(): string {
  const status = getProviderStatus();
  if (!status.configured) {
    return "✗ not configured";
  }
  return `✓ ${status.provider} (${status.model})`;
}

/**
 * Git-backed State Store
 *
 * Stores state in an orphan branch (refs/gen/state) without touching
 * the user's working tree or index. Uses Git plumbing commands with
 * a temporary index file for all write operations.
 *
 * Design Notes:
 * - Uses refs/gen/state (internal ref namespace) to avoid collision with user branches
 * - All writes use GIT_INDEX_FILE with a temp file to not modify user's index
 * - Uses git commit-tree + update-ref with CAS for safe concurrent writes
 * - Reads use git cat-file / git ls-tree without checkout
 * - All keys are stored under .gen-state/ prefix to avoid path collisions
 */

import { execSync, spawnSync } from 'node:child_process'
import { existsSync, mkdtempSync, rmSync, writeFileSync, readFileSync } from 'node:fs'
import { tmpdir } from 'node:os'
import { join, dirname, normalize, isAbsolute } from 'node:path'

// Constants
const STATE_REF = 'refs/gen/state'
const STATE_PREFIX = '.gen-state'
const MANIFEST_PATH = `${STATE_PREFIX}/manifest.json`
const SCHEMA_VERSION = 1
const MAX_VALUE_SIZE = 20 * 1024 * 1024 // 20MB default
const MAX_RETRIES = 3

export interface StateManifest {
  schemaVersion: number
  updatedAt: string
  lastWrite?: {
    key: string
    action: 'put' | 'del' | 'init'
    author?: string
    toolVersion?: string
  }
}

export interface StateStoreOptions {
  maxValueSize?: number
  cwd?: string
}

export class StateStoreError extends Error {
  constructor(
    message: string,
    public code: 'NOT_INITIALIZED' | 'KEY_NOT_FOUND' | 'INVALID_KEY' | 'VALUE_TOO_LARGE' | 'CONCURRENT_UPDATE' | 'GIT_ERROR'
  ) {
    super(message)
    this.name = 'StateStoreError'
  }
}

/**
 * Get the git directory for a repository, handling worktrees correctly
 */
function getGitDir(cwd: string): string {
  try {
    return execSync('git rev-parse --git-dir', {
      cwd,
      encoding: 'utf-8',
      stdio: ['pipe', 'pipe', 'pipe'],
    }).trim()
  } catch {
    throw new StateStoreError('Not a git repository', 'GIT_ERROR')
  }
}

/**
 * Get the common git directory (for worktrees, this is the main .git dir)
 */
function getGitCommonDir(cwd: string): string {
  try {
    return execSync('git rev-parse --git-common-dir', {
      cwd,
      encoding: 'utf-8',
      stdio: ['pipe', 'pipe', 'pipe'],
    }).trim()
  } catch {
    // Fallback to git-dir for older git versions
    return getGitDir(cwd)
  }
}

/**
 * Validate a key to prevent path traversal and other issues
 */
function validateKey(key: string): void {
  if (!key || key.trim() === '') {
    throw new StateStoreError('Key cannot be empty', 'INVALID_KEY')
  }

  // Normalize and check for path traversal
  const normalized = normalize(key)
  if (normalized !== key && !key.includes('/')) {
    throw new StateStoreError(`Invalid key: ${key}`, 'INVALID_KEY')
  }

  // Check for absolute paths
  if (isAbsolute(key)) {
    throw new StateStoreError('Key cannot be an absolute path', 'INVALID_KEY')
  }

  // Check for path traversal
  if (key.includes('..') || key.startsWith('/') || key.includes('\\')) {
    throw new StateStoreError('Key cannot contain path traversal (.. or absolute paths)', 'INVALID_KEY')
  }

  // Check for Windows drive letters
  if (/^[a-zA-Z]:/.test(key)) {
    throw new StateStoreError('Key cannot contain drive letters', 'INVALID_KEY')
  }

  // Check for null bytes
  if (key.includes('\0')) {
    throw new StateStoreError('Key cannot contain null bytes', 'INVALID_KEY')
  }
}

/**
 * Get the full path for a key within the state tree
 */
function getStatePath(key: string): string {
  return `${STATE_PREFIX}/${key}`
}

/**
 * Resolve the current state commit, or null if not initialized
 */
function resolveStateCommit(cwd: string): string | null {
  try {
    const result = execSync(`git rev-parse --verify -q ${STATE_REF}^{commit}`, {
      cwd,
      encoding: 'utf-8',
      stdio: ['pipe', 'pipe', 'pipe'],
    }).trim()
    return result || null
  } catch {
    return null
  }
}

/**
 * Create a blob from content and return its OID
 */
function createBlob(content: string | Buffer, cwd: string): string {
  const result = spawnSync('git', ['hash-object', '-w', '--stdin'], {
    cwd,
    input: content,
    encoding: 'utf-8',
    stdio: ['pipe', 'pipe', 'pipe'],
  })

  if (result.status !== 0) {
    throw new StateStoreError(`Failed to create blob: ${result.stderr}`, 'GIT_ERROR')
  }

  return result.stdout.trim()
}

/**
 * Create a manifest object
 */
function createManifest(action: 'put' | 'del' | 'init', key?: string): StateManifest {
  return {
    schemaVersion: SCHEMA_VERSION,
    updatedAt: new Date().toISOString(),
    lastWrite: {
      key: key || '',
      action,
      toolVersion: 'gitgen',
    },
  }
}

/**
 * Execute a write operation with CAS retry logic
 */
function executeWrite(
  cwd: string,
  operation: (tempIndex: string, currentCommit: string | null) => { tree: string; message: string }
): string {
  let retries = 0

  while (retries < MAX_RETRIES) {
    const currentCommit = resolveStateCommit(cwd)
    const tempIndex = join(mkdtempSync(join(tmpdir(), 'gitgen-state-')), 'index')

    try {
      // Set up temp index with current tree if exists
      const env = { ...process.env, GIT_INDEX_FILE: tempIndex }

      if (currentCommit) {
        execSync(`git read-tree ${currentCommit}^{tree}`, {
          cwd,
          env,
          stdio: ['pipe', 'pipe', 'pipe'],
        })
      }

      // Execute the operation
      const { tree, message } = operation(tempIndex, currentCommit)

      // Create commit
      const parentArgs = currentCommit ? ['-p', currentCommit] : []
      const commitResult = spawnSync('git', ['commit-tree', tree, ...parentArgs, '-m', message], {
        cwd,
        encoding: 'utf-8',
        stdio: ['pipe', 'pipe', 'pipe'],
      })

      if (commitResult.status !== 0) {
        throw new StateStoreError(`Failed to create commit: ${commitResult.stderr}`, 'GIT_ERROR')
      }

      const newCommit = commitResult.stdout.trim()

      // Update ref with CAS
      const updateArgs = currentCommit
        ? ['update-ref', '-m', 'gen state update', STATE_REF, newCommit, currentCommit]
        : ['update-ref', '-m', 'gen state init', STATE_REF, newCommit]

      const updateResult = spawnSync('git', updateArgs, {
        cwd,
        encoding: 'utf-8',
        stdio: ['pipe', 'pipe', 'pipe'],
      })

      if (updateResult.status !== 0) {
        // CAS failed, retry
        retries++
        continue
      }

      return newCommit
    } finally {
      // Clean up temp index
      try {
        rmSync(dirname(tempIndex), { recursive: true, force: true })
      } catch {
        // Ignore cleanup errors
      }
    }
  }

  throw new StateStoreError(
    'Concurrent update detected. Please retry the operation.',
    'CONCURRENT_UPDATE'
  )
}

/**
 * Initialize the state store
 */
export function init(options: StateStoreOptions = {}): string {
  const cwd = options.cwd || process.cwd()

  // Check if already initialized
  const existing = resolveStateCommit(cwd)
  if (existing) {
    return existing
  }

  return executeWrite(cwd, (tempIndex) => {
    const env = { ...process.env, GIT_INDEX_FILE: tempIndex }

    // Create manifest
    const manifest = createManifest('init')
    const manifestBlob = createBlob(JSON.stringify(manifest, null, 2), cwd)

    // Add manifest to index
    execSync(`git update-index --add --cacheinfo 100644 ${manifestBlob} ${MANIFEST_PATH}`, {
      cwd,
      env,
      stdio: ['pipe', 'pipe', 'pipe'],
    })

    // Write tree
    const tree = execSync('git write-tree', {
      cwd,
      env,
      encoding: 'utf-8',
      stdio: ['pipe', 'pipe', 'pipe'],
    }).trim()

    return { tree, message: 'Initialize gen state store' }
  })
}

/**
 * Put a value into the state store
 */
export function put(key: string, source: string | Buffer, options: StateStoreOptions = {}): string {
  const cwd = options.cwd || process.cwd()
  const maxSize = options.maxValueSize || MAX_VALUE_SIZE

  validateKey(key)

  // Read content
  let content: Buffer
  if (Buffer.isBuffer(source)) {
    content = source
  } else if (source === '-') {
    // Read from stdin - this should be handled by the caller
    throw new StateStoreError('Stdin source should be handled by caller', 'GIT_ERROR')
  } else {
    // Read from file
    if (!existsSync(source)) {
      throw new StateStoreError(`Source file not found: ${source}`, 'GIT_ERROR')
    }
    content = readFileSync(source)
  }

  // Check size
  if (content.length > maxSize) {
    throw new StateStoreError(
      `Value too large: ${content.length} bytes (max: ${maxSize} bytes)`,
      'VALUE_TOO_LARGE'
    )
  }

  // Ensure initialized
  const currentCommit = resolveStateCommit(cwd)
  if (!currentCommit) {
    init(options)
  }

  return executeWrite(cwd, (tempIndex) => {
    const env = { ...process.env, GIT_INDEX_FILE: tempIndex }
    const statePath = getStatePath(key)

    // Create blob for content
    const contentBlob = createBlob(content, cwd)

    // Update index with content
    execSync(`git update-index --add --cacheinfo 100644 ${contentBlob} ${statePath}`, {
      cwd,
      env,
      stdio: ['pipe', 'pipe', 'pipe'],
    })

    // Update manifest
    const manifest = createManifest('put', key)
    const manifestBlob = createBlob(JSON.stringify(manifest, null, 2), cwd)
    execSync(`git update-index --add --cacheinfo 100644 ${manifestBlob} ${MANIFEST_PATH}`, {
      cwd,
      env,
      stdio: ['pipe', 'pipe', 'pipe'],
    })

    // Write tree
    const tree = execSync('git write-tree', {
      cwd,
      env,
      encoding: 'utf-8',
      stdio: ['pipe', 'pipe', 'pipe'],
    }).trim()

    return { tree, message: `gen state put: ${key}` }
  })
}

/**
 * Put content directly (for stdin or string content)
 */
export function putContent(key: string, content: string | Buffer, options: StateStoreOptions = {}): string {
  const cwd = options.cwd || process.cwd()
  const maxSize = options.maxValueSize || MAX_VALUE_SIZE

  validateKey(key)

  const buffer = Buffer.isBuffer(content) ? content : Buffer.from(content)

  // Check size
  if (buffer.length > maxSize) {
    throw new StateStoreError(
      `Value too large: ${buffer.length} bytes (max: ${maxSize} bytes)`,
      'VALUE_TOO_LARGE'
    )
  }

  // Ensure initialized
  const currentCommit = resolveStateCommit(cwd)
  if (!currentCommit) {
    init(options)
  }

  return executeWrite(cwd, (tempIndex) => {
    const env = { ...process.env, GIT_INDEX_FILE: tempIndex }
    const statePath = getStatePath(key)

    // Create blob for content
    const contentBlob = createBlob(buffer, cwd)

    // Update index with content
    execSync(`git update-index --add --cacheinfo 100644 ${contentBlob} ${statePath}`, {
      cwd,
      env,
      stdio: ['pipe', 'pipe', 'pipe'],
    })

    // Update manifest
    const manifest = createManifest('put', key)
    const manifestBlob = createBlob(JSON.stringify(manifest, null, 2), cwd)
    execSync(`git update-index --add --cacheinfo 100644 ${manifestBlob} ${MANIFEST_PATH}`, {
