/**
 * Get a value from the state store
 */
export function get(key: string, options: StateStoreOptions = {}): Buffer {
  const cwd = options.cwd || process.cwd()

  validateKey(key)

  const currentCommit = resolveStateCommit(cwd)
  if (!currentCommit) {
    throw new StateStoreError('State store not initialized. Run: git gen state init', 'NOT_INITIALIZED')
  }

  const statePath = getStatePath(key)

  try {
    const result = spawnSync('git', ['cat-file', '-p', `${STATE_REF}:${statePath}`], {
      cwd,
      stdio: ['pipe', 'pipe', 'pipe'],
      maxBuffer: MAX_VALUE_SIZE,
    })

    if (result.status !== 0) {
      throw new StateStoreError(`Key not found: ${key}`, 'KEY_NOT_FOUND')
    }

    return result.stdout
  } catch (error) {
    if (error instanceof StateStoreError) {
      throw error
    }
    throw new StateStoreError(`Key not found: ${key}`, 'KEY_NOT_FOUND')
  }
}

/**
 * Delete a key from the state store
 */
export function del(key: string, options: StateStoreOptions = {}): string {
  const cwd = options.cwd || process.cwd()

  validateKey(key)

  const currentCommit = resolveStateCommit(cwd)
  if (!currentCommit) {
    throw new StateStoreError('State store not initialized. Run: git gen state init', 'NOT_INITIALIZED')
  }

  // Check if key exists
  const statePath = getStatePath(key)
  try {
    execSync(`git cat-file -e ${STATE_REF}:${statePath}`, {
      cwd,
      stdio: ['pipe', 'pipe', 'pipe'],
    })
  } catch {
    throw new StateStoreError(`Key not found: ${key}`, 'KEY_NOT_FOUND')
  }

  return executeWrite(cwd, (tempIndex) => {
    const env = { ...process.env, GIT_INDEX_FILE: tempIndex }

    // Remove from index
    execSync(`git update-index --remove ${statePath}`, {
      cwd,
      env,
      stdio: ['pipe', 'pipe', 'pipe'],
    })

    // Update manifest
    const manifest = createManifest('del', key)
    const manifestBlob = createBlob(JSON.stringify(manifest, null, 2), cwd)
    execSync(`git update-index --add --cacheinfo 100644 ${manifestBlob} ${MANIFEST_PATH}`, {
      cwd,
      env,
      stdio: ['pipe', 'pipe', 'pipe'],
    })

    // Write tree
    const tree = execSync('git write-tree', {
      cwd,
      env,
      encoding: 'utf-8',
      stdio: ['pipe', 'pipe', 'pipe'],
    }).trim()

    return { tree, message: `gen state del: ${key}` }
  })
}

/**
 * List keys in the state store
 */
export function list(prefix?: string, options: StateStoreOptions = {}): string[] {
  const cwd = options.cwd || process.cwd()

  const currentCommit = resolveStateCommit(cwd)
  if (!currentCommit) {
    throw new StateStoreError('State store not initialized. Run: git gen state init', 'NOT_INITIALIZED')
  }

  const searchPath = prefix ? `${STATE_PREFIX}/${prefix}` : STATE_PREFIX

  try {
    const result = execSync(`git ls-tree -r --name-only ${STATE_REF} -- ${searchPath}`, {
      cwd,
      encoding: 'utf-8',
      stdio: ['pipe', 'pipe', 'pipe'],
    })

    const prefixLen = STATE_PREFIX.length + 1 // +1 for the trailing /
    return result
      .trim()
      .split('\n')
      .filter((line) => line && !line.endsWith('manifest.json'))
      .map((line) => line.slice(prefixLen))
      .filter((key) => key) // Remove empty strings
  } catch {
    return []
  }
}

/**
 * Get the current head commit of the state store
 */
export function head(options: StateStoreOptions = {}): string | null {
  const cwd = options.cwd || process.cwd()
  return resolveStateCommit(cwd)
}

/**
 * Check if the state store is initialized
 */
export function isInitialized(options: StateStoreOptions = {}): boolean {
  const cwd = options.cwd || process.cwd()
  return resolveStateCommit(cwd) !== null
}

/**
 * Get the manifest
 */
export function getManifest(options: StateStoreOptions = {}): StateManifest | null {
  const cwd = options.cwd || process.cwd()

  const currentCommit = resolveStateCommit(cwd)
  if (!currentCommit) {
    return null
  }

  try {
    const result = execSync(`git cat-file -p ${STATE_REF}:${MANIFEST_PATH}`, {
      cwd,
      encoding: 'utf-8',
      stdio: ['pipe', 'pipe', 'pipe'],
    })
    return JSON.parse(result)
  } catch {
    return null
  }
}

/**
 * Get a JSON value from the state store
 */
export function getJson<T = unknown>(key: string, options: StateStoreOptions = {}): T | null {
  try {
    const content = get(key, options)
    return JSON.parse(content.toString())
  } catch {
    return null
  }
}

/**
 * Deep merge two objects
 */
function deepMerge(target: Record<string, unknown>, source: Record<string, unknown>): Record<string, unknown> {
  const result: Record<string, unknown> = { ...target }

  for (const key of Object.keys(source)) {
    const sourceValue = source[key]
    const targetValue = result[key]

    if (
      sourceValue &&
      typeof sourceValue === 'object' &&
      !Array.isArray(sourceValue) &&
      targetValue &&
      typeof targetValue === 'object' &&
      !Array.isArray(targetValue)
    ) {
      result[key] = deepMerge(
        targetValue as Record<string, unknown>,
        sourceValue as Record<string, unknown>
      )
    } else {
      result[key] = sourceValue
    }
  }

  return result
}

/**
 * Set a value at a specific path in a JSON object
 * Path uses dot notation: "user.settings.theme"
 */
function setAtPath(obj: Record<string, unknown>, path: string, value: unknown): Record<string, unknown> {
  const parts = path.split('.')
  const result = { ...obj }
  let current: Record<string, unknown> = result

  for (let i = 0; i < parts.length - 1; i++) {
    const part = parts[i]
    if (!(part in current) || typeof current[part] !== 'object' || current[part] === null) {
      current[part] = {}
    } else {
      current[part] = { ...(current[part] as Record<string, unknown>) }
    }
    current = current[part] as Record<string, unknown>
  }

  current[parts[parts.length - 1]] = value
  return result
}

/**
 * Set a value at a path within a JSON key
 * Creates the key if it doesn't exist
 */
export function set(
  key: string,
  path: string,
  value: unknown,
  options: StateStoreOptions = {}
): string {
  const cwd = options.cwd || process.cwd()

  validateKey(key)

  // Ensure initialized
  if (!resolveStateCommit(cwd)) {
    init(options)
  }

  // Get existing content or start with empty object
  let existing: Record<string, unknown> = {}
  try {
    const content = get(key, options)
    existing = JSON.parse(content.toString())
    if (typeof existing !== 'object' || existing === null || Array.isArray(existing)) {
      existing = {}
    }
  } catch {
    // Key doesn't exist, start fresh
  }

  // Set value at path
  const updated = setAtPath(existing, path, value)
  return putContent(key, JSON.stringify(updated, null, 2), options)
}

/**
 * Deep merge content into an existing JSON key
 * Creates the key if it doesn't exist
 */
export function merge(
  key: string,
  content: Record<string, unknown>,
  options: StateStoreOptions = {}
): string {
  const cwd = options.cwd || process.cwd()

  validateKey(key)

  // Ensure initialized
  if (!resolveStateCommit(cwd)) {
    init(options)
  }

  // Get existing content or start with empty object
  let existing: Record<string, unknown> = {}
  try {
    const existingContent = get(key, options)
    existing = JSON.parse(existingContent.toString())
    if (typeof existing !== 'object' || existing === null || Array.isArray(existing)) {
      existing = {}
    }
  } catch {
    // Key doesn't exist, start fresh
  }

  // Deep merge
  const merged = deepMerge(existing, content)
  return putContent(key, JSON.stringify(merged, null, 2), options)
}

// Export all functions as a namespace for convenience
export const stateStore = {
  init,
  put,
  putContent,
  get,
  getJson,
  set,
  merge,
  del,
  list,
  head,
  isInitialized,
  getManifest,
  STATE_REF,
  StateStoreError,
}

export default stateStore

