 */
export function mergestat(sql, cwd) {
    const repoPath = cwd || process.cwd();
    return execSync(`docker run --rm --entrypoint /app/mergestat -v "${repoPath}:/repo" -w /repo mergestat/mergestat "${sql.replace(/"/g, '\\"')}"`, {
        encoding: 'utf-8',
