 */
export function mergestatJson(sql, cwd) {
    if (!isAvailable())
        return [];
    try {
        const repoPath = cwd || process.cwd();
        const result = execSync(`docker run --rm --entrypoint /app/mergestat -v "${repoPath}:/repo" -w /repo mergestat/mergestat --format json "${sql.replace(/"/g, '\\"')}"`, {
