/**
 * Claude Code agentic controller
 *
 * This controller provides full autonomous operation capabilities:
 * - Maintains conversation history for context
 * - Exposes tools for file manipulation and command execution
 * - Supports iterative planning and refinement
 * - Can run autonomous loops to complete objectives
 */
export class ClaudeCodeController extends BaseController implements AgenticController {
  readonly type: ControllerType = 'claude-code';

  private conversationState: ConversationState;
  private loopState: LoopStateManager;
  private tools: Map<string, Tool> = new Map();
  private currentPlan: Plan | undefined;

  constructor() {
    super();
    this.conversationState = new ConversationState({ maxMessages: 100 });
    this.loopState = new LoopStateManager();
  }

  // === Lifecycle ===

  async initialize(context: ExecutionContext): Promise<void> {
    await super.initialize(context);

    // Initialize default tools
    const defaultTools = createDefaultTools(
      this.getWorkingDir(),
      () => this.currentPlan,
      async (plan) => { this.currentPlan = plan; await this.savePlanToFile(plan); }
    );

    for (const tool of defaultTools) {
      this.tools.set(tool.name, tool);
    }

    // Set up system prompt
    this.conversationState.setSystemPrompt(this.getSystemPrompt());
  }

  async shutdown(): Promise<void> {
    this.conversationState.reset();
    this.loopState.clear();
    this.tools.clear();
    this.currentPlan = undefined;
    await super.shutdown();
  }

  private getSystemPrompt(): string {
    const context = this.getContext();
    return `You are an AI assistant helping with code generation and software development.

CONTEXT:
- Working Directory: ${context.workingDir}
${context.worktreeDir ? `- Worktree: ${context.worktreeDir}` : ''}
- Controller: Claude Code (agentic)
${context.dryRun ? '- Mode: Dry Run (no file writes)' : ''}

You have access to tools for reading, writing, and editing files, executing commands,
searching the codebase, and managing plans. Use these tools to complete objectives.

When working on a plan:
1. Mark steps as in_progress when you start them
2. Mark steps as completed when you finish them
3. Update the CHANGELOG.md as you complete features
4. Commit changes at logical checkpoints`;
  }

  // === Output ===

  output(message: string, level: OutputLevel = 'info'): void {
    // In Claude Code context, we format output for the conversation
    const prefix = level === 'error' ? '❌ ' : level === 'warn' ? '⚠️ ' : '';
    const formatted = `${prefix}${message}`;

    // Add to conversation as assistant message if it's significant
    if (level === 'info' || level === 'error') {
      this.conversationState.addMessage('assistant', formatted);
    }

    // Also log to console
    if (level === 'error') {
      console.error(formatted);
    } else {
      console.log(formatted);
    }
  }

  // === Conversation State ===

  getConversationHistory(): ConversationMessage[] {
    return this.conversationState.getMessages();
  }

  addMessage(role: 'user' | 'assistant', content: string): void {
    this.conversationState.addMessage(role, content);
  }

  clearHistory(): void {
    this.conversationState.clear();
  }

  // === Tool Interface ===

  getAvailableTools(): Tool[] {
    return Array.from(this.tools.values());
  }

  async executeTool(name: string, params: Record<string, unknown>): Promise<ToolResult> {
    const tool = this.tools.get(name);
    if (!tool) {
      return {
        success: false,
        output: '',
        error: `Unknown tool: ${name}`,
      };
    }

    this.emit({
      type: 'tool:execute',
      timestamp: new Date(),
      data: { tool: name, params },
    });

    try {
      return await tool.execute(params);
    } catch (error) {
      return {
        success: false,
        output: '',
        error: (error as Error).message,
      };
    }
  }

  registerTool(tool: Tool): void {
    this.tools.set(tool.name, tool);
  }

  // === Planning ===

  async createPlan(objective: string): Promise<Plan> {
    const plan: Plan = {
      id: `plan-${Date.now()}`,
      feature: objective,
      status: 'pending',
      steps: [],
      commits: [],
      specPath: '',
      outputPath: '',
      createdAt: new Date(),
      updatedAt: new Date(),
    };

    this.currentPlan = plan;
    return plan;
  }

  async reviewAndRefine(result: CommandResult): Promise<CommandResult> {
    // In a full implementation, this would use the LLM to review the result
    // and potentially make refinements
    return result;
  }

  // === Autonomous Loop ===

  async runLoop(objective: string, maxIterations = 10): Promise<CommandResult> {
    const state = this.loopState.start(objective, maxIterations);

    this.emit({
      type: 'loop:start',
      timestamp: new Date(),
      data: { objective, maxIterations },
    });

    this.addMessage('user', `Objective: ${objective}`);

    try {
      while (this.loopState.isRunning() && !this.loopState.isMaxReached()) {
        const iteration = this.loopState.nextIteration();

        this.emit({
          type: 'loop:iteration',
          timestamp: new Date(),
          data: { iteration },
        });

        // In a full implementation, this would:
        // 1. Call the LLM with conversation history
        // 2. Parse tool calls from response
        // 3. Execute tools
        // 4. Add results to conversation
        // 5. Check if objective is complete

        // For now, we just track the iteration
        this.loopState.recordStep(`Iteration ${iteration}`);

        // Break after one iteration in this stub implementation
        break;
      }

      this.loopState.stop();

      this.emit({
        type: 'loop:complete',
        timestamp: new Date(),
        data: { summary: this.loopState.getSummary() },
      });

      return {
        success: true,
        message: this.loopState.getSummary(),
      };
    } catch (error) {
      this.loopState.recordError((error as Error).message);
      this.loopState.stop();

      return {
        success: false,
        message: 'Loop failed',
        errors: [(error as Error).message],
      };
    }
  }

  stopLoop(): void {
    this.loopState.stop();
  }

  isLoopRunning(): boolean {
    return this.loopState.isRunning();
  }

  // === Generation Hooks ===

  async beforeGeneration(options: GenerationOptions): Promise<GenerationOptions> {
    await super.beforeGeneration(options);

    // Add generation context to conversation
    this.addMessage('user', `Generate: ${options.feature}`);

    return options;
  }

  async afterGeneration(result: CommandResult): Promise<CommandResult> {
    await super.afterGeneration(result);

    // Add result to conversation
    if (result.success) {
      this.addMessage('assistant', `Generated ${result.files?.length || 0} files`);
    } else {
      this.addMessage('assistant', `Generation failed: ${result.message}`);
    }

    return result;
  }

  // === Prompt Context ===

  injectContext(basePrompt: string): string {
    const context = this.getContext();
    const tools = this.getAvailableTools();

    const toolList = tools.map(t => `- ${t.name}: ${t.description}`).join('\n');

    const contextInfo = [
      'EXECUTION CONTEXT:',
      `- Controller: Claude Code (agentic)`,
      `- Working Directory: ${context.workingDir}`,
      context.worktreeDir ? `- Worktree: ${context.worktreeDir}` : null,
      context.dryRun ? '- Mode: Dry Run (no file writes)' : null,
      '',
      'AVAILABLE TOOLS:',
      toolList,
      '',
      this.currentPlan ? `ACTIVE PLAN: ${this.currentPlan.feature}` : null,
      '',
    ].filter(Boolean).join('\n');

    return `${basePrompt}\n\n${contextInfo}`;
  }

  // === Plan File Management ===

  private async savePlanToFile(plan: Plan): Promise<void> {
    if (!plan.outputPath) {
      plan.outputPath = join(this.getWorkingDir(), 'PLAN.md');
    }

    const content = this.formatPlanAsMarkdown(plan);
    await writeFile(plan.outputPath, content, 'utf-8');
  }

  private formatPlanAsMarkdown(plan: Plan): string {
    const statusIcon = (status: string) => {
      switch (status) {
        case 'completed': return '✅';
        case 'in_progress': return '🔄';
        case 'skipped': return '⏭️';
        default: return '⏳';
      }
    };

    const lines = [
      `# Plan: ${plan.feature}`,
      '',
      `**Status:** ${plan.status}`,
      `**Created:** ${plan.createdAt.toISOString()}`,
      `**Updated:** ${plan.updatedAt.toISOString()}`,
      '',
      '## Steps',
      '',
    ];

    for (const step of plan.steps) {
      lines.push(`- ${statusIcon(step.status)} **${step.id}**: ${step.description}`);
      if (step.files.length > 0) {
        lines.push(`  - Files: ${step.files.join(', ')}`);
      }
    }

    if (plan.commits.length > 0) {
      lines.push('', '## Commits', '');
      for (const commit of plan.commits) {
        lines.push(`- \`${commit.hash}\`: ${commit.message}`);
      }
    }

    return lines.join('\n');
  }
}

