  additions: number
  deletions: number
}

/**
 * Query files by path pattern
 */
export function queryFiles(pattern: string, cwd?: string): FileResult[] {
  const sql = `SELECT path, contents FROM files('', 'HEAD') WHERE path LIKE '%${pattern}%' LIMIT 10`
  return mergestatJson<FileResult[]>(sql, cwd)
}

/**
 * Query commits by message pattern
 */
export function queryCommits(pattern: string, limit = 10, cwd?: string): CommitResult[] {
  const sql = `SELECT hash, message, author_email, author_date FROM commits WHERE message LIKE '%${pattern}%' ORDER BY author_date DESC LIMIT ${limit}`
  return mergestatJson<CommitResult[]>(sql, cwd)
}

/**
 * Get file change stats
 */
export function queryStats(pattern: string, cwd?: string): StatsResult[] {
  const sql = `SELECT file, additions, deletions FROM stats WHERE file LIKE '%${pattern}%'`
  return mergestatJson<StatsResult[]>(sql, cwd)
}

/**
 * Get most frequently changed files
 */
export function queryHotFiles(limit = 20, cwd?: string): Array<{ file: string; changes: number }> {
  const sql = `SELECT file, COUNT(*) as changes FROM stats GROUP BY file ORDER BY changes DESC LIMIT ${limit}`
  return mergestatJson(sql, cwd)
}

/**
 * Get tech stack from file extensions
 */
export function queryTechStack(cwd?: string): Array<{ language: string; file_count: number }> {
  const sql = `
    SELECT
      CASE
        WHEN path LIKE '%.ts' OR path LIKE '%.tsx' THEN 'typescript'
        WHEN path LIKE '%.js' OR path LIKE '%.jsx' THEN 'javascript'
        WHEN path LIKE '%.py' THEN 'python'
        WHEN path LIKE '%.go' THEN 'go'
        WHEN path LIKE '%.rs' THEN 'rust'
        WHEN path LIKE '%.java' THEN 'java'
        WHEN path LIKE '%.rb' THEN 'ruby'
        WHEN path LIKE '%.php' THEN 'php'
        WHEN path LIKE '%.cs' THEN 'csharp'
        WHEN path LIKE '%.cpp' OR path LIKE '%.cc' THEN 'cpp'
        WHEN path LIKE '%.c' THEN 'c'
        WHEN path LIKE '%.swift' THEN 'swift'
        WHEN path LIKE '%.kt' THEN 'kotlin'
        ELSE NULL
      END as language,
      COUNT(*) as file_count
    FROM files('', 'HEAD')
    WHERE language IS NOT NULL
    GROUP BY language
    ORDER BY file_count DESC
  `.replace(/\n/g, ' ')
  return mergestatJson(sql, cwd)
}

